-- ============================================================================
-- HUNTER SYSTEM - 0001 CORE SCHEMA
-- ----------------------------------------------------------------------------
-- Applied on a fresh Supabase project (Postgres 15+). Assumes the platform
-- already provides: schema `auth`, table `auth.users`, roles `anon`,
-- `authenticated`, `service_role`, and function `auth.uid()`.
-- Use a locally installed Postgres for tests: see supabase/tests/README.md
-- ============================================================================

create extension if not exists pgcrypto;

-- ----------------------------------------------------------------------------
-- Enumerations
-- ----------------------------------------------------------------------------
create type public.session_status as enum ('active', 'paused', 'completed', 'cancelled');
create type public.topic_status as enum ('not_started', 'learning', 'revised', 'mastered');
create type public.quest_category as enum ('daily', 'weekly', 'special');
create type public.quest_difficulty as enum ('easy', 'normal', 'hard', 'elite');
create type public.quest_status as enum ('active', 'completed', 'expired');
create type public.xp_source as enum ('session', 'quest', 'achievement', 'bonus');
create type public.notification_type as enum ('session', 'xp', 'level', 'rank', 'quest', 'achievement', 'system', 'report');
create type public.hunter_role as enum ('hunter', 'moderator', 'admin');

-- ----------------------------------------------------------------------------
-- Tunable progression configuration (single row, server owned)
-- ----------------------------------------------------------------------------
create table public.progression_config (
  id                  integer primary key default 1 check (id = 1),
  xp_per_minute       integer not null default 1 check (xp_per_minute between 0 and 10),
  base_level_xp       integer not null default 100 check (base_level_xp > 0),
  level_growth_xp     integer not null default 25 check (level_growth_xp >= 0),
  daily_xp_cap        integer not null default 720 check (daily_xp_cap > 0),
  min_session_seconds integer not null default 60 check (min_session_seconds >= 0),
  max_session_seconds integer not null default 21600 check (max_session_seconds > 0),
  max_heartbeat_gap   integer not null default 150 check (max_heartbeat_gap >= 30),
  updated_at          timestamptz not null default now()
);

insert into public.progression_config (id) values (1);

-- Rank ladder. Ordering is explicit so the ladder can be rebalanced later
-- without touching code.
create table public.rank_thresholds (
  rank        text primary key check (rank in ('F','E','D','C','B','A','S')),
  min_xp      bigint not null unique check (min_xp >= 0),
  order_index integer not null unique check (order_index >= 0)
);

insert into public.rank_thresholds (rank, min_xp, order_index) values
  ('F', 0, 0),
  ('E', 500, 1),
  ('D', 1500, 2),
  ('C', 3000, 3),
  ('B', 6000, 4),
  ('A', 10000, 5),
  ('S', 15000, 6);

-- ----------------------------------------------------------------------------
-- Profiles (1:1 with auth.users)
-- ----------------------------------------------------------------------------
create table public.profiles (
  id                   uuid primary key references auth.users (id) on delete cascade,
  hunter_id            text not null unique
                         default ('H-' || upper(encode(gen_random_bytes(4), 'hex'))),
  username             text not null,
  display_name         text,
  avatar_url           text check (avatar_url is null or char_length(avatar_url) <= 512),
  bio                  text check (bio is null or char_length(bio) <= 500),
  timezone             text not null default 'UTC',
  is_public            boolean not null default true,
  show_on_leaderboard  boolean not null default true,
  -- Progression state. Server-owned: never writable by the client.
  xp_total             bigint not null default 0 check (xp_total >= 0),
  level                integer not null default 1 check (level >= 1),
  rank                 text not null default 'F' check (rank in ('F','E','D','C','B','A','S')),
  -- Denormalised aggregates, maintained by triggers.
  total_study_seconds  bigint not null default 0 check (total_study_seconds >= 0),
  sessions_completed   integer not null default 0 check (sessions_completed >= 0),
  quests_completed     integer not null default 0 check (quests_completed >= 0),
  achievements_count   integer not null default 0 check (achievements_count >= 0),
  current_streak       integer not null default 0 check (current_streak >= 0),
  longest_streak       integer not null default 0 check (longest_streak >= 0),
  last_study_date      date,
  daily_goal_minutes   integer not null default 60
                         check (daily_goal_minutes between 15 and 1440),
  role                 public.hunter_role not null default 'hunter',
  awakened_at          timestamptz,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  constraint profiles_username_format check (username ~ '^[A-Za-z0-9_]{3,20}$')
);

create unique index profiles_username_lower_idx on public.profiles (lower(username));
create index profiles_leaderboard_idx
  on public.profiles (xp_total desc, created_at asc)
  where is_public and show_on_leaderboard;

-- ----------------------------------------------------------------------------
-- Subjects / topics
-- ----------------------------------------------------------------------------
create table public.subjects (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  title       text not null check (char_length(btrim(title)) between 1 and 60),
  color       text not null default '#38bdf8' check (color ~ '^#[0-9A-Fa-f]{6}$'),
  icon        text,
  target_minutes_per_week integer check (target_minutes_per_week is null or target_minutes_per_week between 0 and 10080),
  archived    boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index subjects_user_idx on public.subjects (user_id, archived);
create unique index subjects_user_title_idx on public.subjects (user_id, lower(btrim(title)));

create table public.topics (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  subject_id   uuid not null references public.subjects (id) on delete cascade,
  title        text not null check (char_length(btrim(title)) between 1 and 120),
  status       public.topic_status not null default 'not_started',
  revision_count integer not null default 0 check (revision_count >= 0),
  last_revised_at timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index topics_subject_idx on public.topics (subject_id, status);
create index topics_user_idx on public.topics (user_id);
create unique index topics_subject_title_idx on public.topics (subject_id, lower(btrim(title)));

-- ----------------------------------------------------------------------------
-- Study sessions
-- ----------------------------------------------------------------------------
create table public.study_sessions (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references public.profiles (id) on delete cascade,
  subject_id       uuid references public.subjects (id) on delete set null,
  topic_id         uuid references public.topics (id) on delete set null,
  client_token     uuid not null,
  planned_seconds  integer not null check (planned_seconds between 60 and 43200),
  is_revision      boolean not null default false,
  note             text check (note is null or char_length(note) <= 280),
  status           public.session_status not null default 'active',
  started_at       timestamptz not null default now(),
  ended_at         timestamptz,
  paused_seconds   integer not null default 0 check (paused_seconds >= 0),
  duration_seconds integer check (duration_seconds is null or duration_seconds >= 0),
  credited_minutes integer check (credited_minutes is null or credited_minutes >= 0),
  xp_awarded       integer not null default 0 check (xp_awarded >= 0),
  created_at       timestamptz not null default now(),
  constraint study_sessions_token_unique unique (user_id, client_token),
  constraint study_sessions_time_order check (ended_at is null or ended_at >= started_at)
);

create index study_sessions_user_started_idx on public.study_sessions (user_id, started_at desc);
create index study_sessions_user_status_idx on public.study_sessions (user_id, status);
create index study_sessions_completed_idx
  on public.study_sessions (user_id, started_at desc)
  where status = 'completed';
-- One live session per hunter at a time.
create unique index study_sessions_one_active_idx
  on public.study_sessions (user_id)
  where status in ('active', 'paused');

create table public.study_session_pauses (
  id          bigserial primary key,
  session_id  uuid not null references public.study_sessions (id) on delete cascade,
  user_id     uuid not null references public.profiles (id) on delete cascade,
  paused_at   timestamptz not null default now(),
  resumed_at  timestamptz,
  constraint pauses_order check (resumed_at is null or resumed_at >= paused_at)
);

create index pauses_session_idx on public.study_session_pauses (session_id, paused_at);
create unique index pauses_one_open_idx
  on public.study_session_pauses (session_id)
  where resumed_at is null;

-- Server-stamped heartbeats. Credited time is derived from these, so a client
-- that simply leaves the tab open is not rewarded.
create table public.study_session_heartbeats (
  id         bigserial primary key,
  session_id uuid not null references public.study_sessions (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  seen_at    timestamptz not null default now()
);

create index heartbeats_session_idx on public.study_session_heartbeats (session_id, seen_at);

-- ----------------------------------------------------------------------------
-- XP ledger — the single source of truth for earned experience
-- ----------------------------------------------------------------------------
create table public.xp_transactions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id) on delete cascade,
  source_type public.xp_source not null,
  source_id   uuid,
  amount      integer not null check (amount > 0),
  detail      jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);

-- A given source can only ever pay out once (sessions, quests, achievements).
create unique index xp_transactions_source_unique
  on public.xp_transactions (user_id, source_type, source_id)
  where source_id is not null;

create index xp_transactions_user_created_idx on public.xp_transactions (user_id, created_at desc);
create index xp_transactions_period_idx on public.xp_transactions (created_at desc, user_id);

-- ----------------------------------------------------------------------------
-- Quests
-- ----------------------------------------------------------------------------
create table public.quest_templates (
  code         text primary key,
  category     public.quest_category not null,
  difficulty   public.quest_difficulty not null,
  title        text not null,
  description  text not null,
  metric       text not null,
  target_value numeric not null check (target_value > 0),
  reward_xp    integer not null check (reward_xp > 0),
  recurrence   text not null check (recurrence in ('daily', 'weekly', 'once')),
  sort_order   integer not null default 0
);

create table public.quests (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references public.profiles (id) on delete cascade,
  template_code  text not null references public.quest_templates (code) on delete cascade,
  title          text not null,
  description    text not null,
  category       public.quest_category not null,
  difficulty     public.quest_difficulty not null,
  metric         text not null,
  target_value   numeric not null,
  progress_value numeric not null default 0,
  reward_xp      integer not null,
  period_key     text not null,
  starts_at      timestamptz not null,
  ends_at        timestamptz not null,
  status         public.quest_status not null default 'active',
  completed_at   timestamptz,
  created_at     timestamptz not null default now(),
  constraint quests_unique_period unique (user_id, template_code, period_key),
  constraint quests_window check (ends_at > starts_at)
);

create index quests_user_status_idx on public.quests (user_id, status, ends_at desc);
create index quests_user_category_idx on public.quests (user_id, category, status);

-- ----------------------------------------------------------------------------
-- Achievements
-- ----------------------------------------------------------------------------
create table public.achievements (
  code         text primary key,
  name         text not null,
  description  text not null,
  icon         text not null,
  metric       text not null,
  target_value numeric not null,
  rarity       text not null check (rarity in ('common', 'rare', 'epic', 'legendary')),
  reward_xp    integer not null default 0 check (reward_xp >= 0),
  sort_order   integer not null default 0
);

create table public.user_achievements (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references public.profiles (id) on delete cascade,
  achievement_code text not null references public.achievements (code) on delete cascade,
  unlocked_at    timestamptz not null default now(),
  unique (user_id, achievement_code)
);

create index user_achievements_user_idx on public.user_achievements (user_id, unlocked_at desc);

-- ----------------------------------------------------------------------------
-- Notifications (in-app only)
-- ----------------------------------------------------------------------------
create table public.notifications (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  type       public.notification_type not null default 'system',
  title      text not null,
  message    text not null,
  payload    jsonb not null default '{}'::jsonb,
  is_read    boolean not null default false,
  created_at timestamptz not null default now()
);

create index notifications_user_idx on public.notifications (user_id, created_at desc);
create index notifications_unread_idx on public.notifications (user_id) where not is_read;

-- ----------------------------------------------------------------------------
-- Abuse protection
-- ----------------------------------------------------------------------------
create table public.rate_limit_events (
  id         bigserial primary key,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  action     text not null,
  created_at timestamptz not null default now()
);

create index rate_limit_lookup_idx on public.rate_limit_events (user_id, action, created_at desc);


-- ############################################################################
-- ## 0002_progression.sql
-- ############################################################################

-- ============================================================================
-- HUNTER SYSTEM - 0002 PROGRESSION MATH, METRICS, TRIGGERS
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Level curve
--   xp needed for next level = base + (level - 1) * growth
--   cumulative xp to *be* at level L = base*(L-1) + growth*(L-1)*(L-2)/2
-- ----------------------------------------------------------------------------
create or replace function public.level_step_xp(p_level integer, p_base integer, p_growth integer)
returns bigint
language sql
immutable
as $$
  select greatest(1, p_base + (greatest(p_level, 1) - 1) * p_growth)::bigint;
$$;

create or replace function public.xp_to_reach_level(p_level integer, p_base integer, p_growth integer)
returns bigint
language sql
immutable
as $$
  select case
           when p_level <= 1 then 0::bigint
           else (p_base::bigint * (p_level - 1))
                + (p_growth::bigint * (p_level - 1) * (p_level - 2)) / 2
         end;
$$;

-- Closed-form inverse with a small correction loop, so it stays exact for any
-- (base, growth) pair the configuration may use later.
create or replace function public.level_for_xp(p_xp bigint, p_base integer, p_growth integer)
returns integer
language plpgsql
immutable
as $$
declare
  v_xp     bigint := greatest(coalesce(p_xp, 0), 0);
  v_level  integer;
  v_b      numeric;
  v_a      numeric;
  v_c      numeric;
  v_guess  numeric;
begin
  if p_growth is null or p_growth <= 0 then
    return (v_xp / greatest(p_base, 1))::integer + 1;
  end if;

  -- growth*n^2 + (2*base - growth)*n - 2*xp = 0  where n = level - 1
  v_a := p_growth;
  v_b := (2 * p_base) - p_growth;
  v_c := -2 * v_xp;
  v_guess := (-v_b + sqrt(v_b * v_b - 4 * v_a * v_c)) / (2 * v_a);
  v_level := greatest(1, floor(v_guess)::integer + 1);

  -- Correct for integer truncation / floating point drift.
  while v_level > 1 and public.xp_to_reach_level(v_level, p_base, p_growth) > v_xp loop
    v_level := v_level - 1;
  end loop;
  while public.xp_to_reach_level(v_level + 1, p_base, p_growth) <= v_xp loop
    v_level := v_level + 1;
  end loop;

  return v_level;
end;
$$;

-- Config-aware wrappers used by triggers and the app.
create or replace function public.hunter_progression()
returns public.progression_config
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select * from public.progression_config where id = 1;
$$;

create or replace function public.level_for_xp(p_xp bigint)
returns integer
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.level_for_xp(p_xp, c.base_level_xp, c.level_growth_xp)
    from public.progression_config c where c.id = 1;
$$;

create or replace function public.level_progress(p_xp bigint)
returns table (
  level          integer,
  level_xp_start bigint,
  level_xp_next  bigint,
  into_level     bigint,
  needed         bigint,
  percent        numeric
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_cfg   public.progression_config;
  v_level integer;
  v_start bigint;
  v_next  bigint;
  v_into  bigint;
  v_need  bigint;
begin
  select * into v_cfg from public.progression_config where id = 1;
  v_level := public.level_for_xp(p_xp, v_cfg.base_level_xp, v_cfg.level_growth_xp);
  v_start := public.xp_to_reach_level(v_level, v_cfg.base_level_xp, v_cfg.level_growth_xp);
  v_next  := public.xp_to_reach_level(v_level + 1, v_cfg.base_level_xp, v_cfg.level_growth_xp);
  v_into  := greatest(0, coalesce(p_xp, 0) - v_start);
  v_need  := greatest(1, v_next - v_start);

  return query select v_level, v_start, v_next, v_into, v_need,
    round((v_into::numeric / v_need::numeric) * 100, 2);
end;
$$;

create or replace function public.rank_for_xp(p_xp bigint)
returns text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select t.rank
    from public.rank_thresholds t
   where t.min_xp <= greatest(coalesce(p_xp, 0), 0)
   order by t.min_xp desc
   limit 1;
$$;

create or replace function public.rank_index(p_rank text)
returns integer
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce((select order_index from public.rank_thresholds where rank = p_rank), 0);
$$;

-- ----------------------------------------------------------------------------
-- Derived productivity metrics (single implementation used by quests,
-- achievements and analytics so numbers can never disagree)
-- ----------------------------------------------------------------------------
create or replace function public.hunter_metric(p_metric text, p_user uuid, p_now timestamptz default now())
returns numeric
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_tz          text;
  v_today       date;
  v_day_start   timestamptz;
  v_week_start  timestamptz;
  v_month_start timestamptz;
  v_value       numeric := 0;
  v_profile     public.profiles;
begin
  select * into v_profile from public.profiles where id = p_user;
  if not found then
    return 0;
  end if;

  v_tz := coalesce(nullif(v_profile.timezone, ''), 'UTC');
  begin
    execute 'select ($1 at time zone $2)::date' into v_today using p_now, v_tz;
    execute 'select (($1::date)::timestamp at time zone $2)' into v_day_start using v_today, v_tz;
    execute 'select ((date_trunc(''week'', $1::date)::timestamp) at time zone $2)'
      into v_week_start using v_today, v_tz;
    execute 'select ((date_trunc(''month'', $1::date)::timestamp) at time zone $2)'
      into v_month_start using v_today, v_tz;
  exception when others then
    -- Unknown timezone: fall back to UTC rather than failing the request.
    v_tz := 'UTC';
    v_today := (p_now at time zone 'UTC')::date;
    v_day_start := (v_today::timestamp at time zone 'UTC');
    v_week_start := (date_trunc('week', v_today::timestamp) at time zone 'UTC');
    v_month_start := (date_trunc('month', v_today::timestamp) at time zone 'UTC');
  end;

  case p_metric
    -- ---------- today ----------
    when 'study_minutes_day' then
      select coalesce(sum(s.credited_minutes), 0) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and s.started_at >= v_day_start and coalesce(s.credited_minutes, 0) > 0;

    when 'sessions_day' then
      select count(*) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and s.started_at >= v_day_start and coalesce(s.credited_minutes, 0) > 0;

    when 'distinct_subjects_day' then
      select count(distinct s.subject_id) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and s.started_at >= v_day_start and coalesce(s.credited_minutes, 0) > 0
         and s.subject_id is not null;

    when 'max_session_minutes_day' then
      select coalesce(max(s.credited_minutes), 0) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and s.started_at >= v_day_start;

    when 'revision_sessions_day' then
      select count(*) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed' and s.is_revision
         and s.started_at >= v_day_start and coalesce(s.credited_minutes, 0) > 0;

    -- ---------- this week ----------
    when 'study_minutes_week' then
      select coalesce(sum(s.credited_minutes), 0) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and s.started_at >= v_week_start and coalesce(s.credited_minutes, 0) > 0;

    when 'sessions_week' then
      select count(*) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and s.started_at >= v_week_start and coalesce(s.credited_minutes, 0) > 0;

    when 'distinct_subjects_week' then
      select count(distinct s.subject_id) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and s.started_at >= v_week_start and coalesce(s.credited_minutes, 0) > 0
         and s.subject_id is not null;

    when 'revision_topics_week' then
      select count(*) into v_value
        from public.topics t
       where t.user_id = p_user and t.last_revised_at is not null
         and t.last_revised_at >= v_week_start;

    when 'study_minutes_month' then
      select coalesce(sum(s.credited_minutes), 0) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and s.started_at >= v_month_start and coalesce(s.credited_minutes, 0) > 0;

    -- ---------- lifetime ----------
    when 'xp_total' then
      v_value := v_profile.xp_total;

    when 'level' then
      v_value := v_profile.level;

    when 'rank_index' then
      v_value := public.rank_index(v_profile.rank);

    when 'sessions_total' then
      select count(*) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and coalesce(s.credited_minutes, 0) > 0;

    when 'study_minutes_total' then
      select coalesce(sum(s.credited_minutes), 0) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and coalesce(s.credited_minutes, 0) > 0;

    when 'distinct_days' then
      select count(distinct (s.started_at at time zone v_tz)::date)::numeric
        into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and coalesce(s.credited_minutes, 0) > 0;

    when 'current_streak' then
      v_value := v_profile.current_streak;

    when 'longest_streak' then
      v_value := v_profile.longest_streak;

    when 'max_session_minutes_total' then
      select coalesce(max(s.credited_minutes), 0) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed';

    when 'early_sessions' then
      select count(*) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and coalesce(s.credited_minutes, 0) > 0
         and extract(hour from (s.started_at at time zone v_tz)) < 6;

    when 'night_sessions' then
      select count(*) into v_value
        from public.study_sessions s
       where s.user_id = p_user and s.status = 'completed'
         and coalesce(s.credited_minutes, 0) > 0
         and extract(hour from (s.started_at at time zone v_tz)) >= 23;

    when 'achievements_count' then
      v_value := v_profile.achievements_count;

    when 'quests_completed' then
      v_value := v_profile.quests_completed;

    else
      raise exception 'Unknown metric: %', p_metric using errcode = '22023';
  end case;

  return coalesce(v_value, 0);
end;
$$;

-- ----------------------------------------------------------------------------
-- Triggers: keep profiles consistent and emit System notifications
-- ----------------------------------------------------------------------------
create or replace function public.tg_profiles_before_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  new.updated_at := now();
  new.username := btrim(new.username);
  if new.xp_total is distinct from old.xp_total or new.level = 0 then
    new.level := public.level_for_xp(new.xp_total);
    new.rank := public.rank_for_xp(new.xp_total);
  end if;
  return new;
end;
$$;

create trigger profiles_before_update
  before update on public.profiles
  for each row execute function public.tg_profiles_before_update();

create or replace function public.tg_touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger subjects_touch before update on public.subjects
  for each row execute function public.tg_touch_updated_at();
create trigger topics_touch before update on public.topics
  for each row execute function public.tg_touch_updated_at();

-- Applying XP: the only place xp_total may move.
create or replace function public.tg_xp_applied()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_level_before integer;
  v_rank_before  text;
  v_level_after  integer;
  v_rank_after   text;
begin
  select level, rank into v_level_before, v_rank_before
    from public.profiles where id = new.user_id
   for update;

  update public.profiles
     set xp_total = xp_total + new.amount
   where id = new.user_id
  returning level, rank into v_level_after, v_rank_after;

  if v_level_after > v_level_before then
    insert into public.notifications (user_id, type, title, message, payload)
    values (
      new.user_id,
      'level',
      'LEVEL PROGRESSION AVAILABLE',
      format('You have reached Level %s.', v_level_after),
      jsonb_build_object('level_before', v_level_before, 'level_after', v_level_after)
    );
  end if;

  if public.rank_index(v_rank_after) > public.rank_index(v_rank_before) then
    insert into public.notifications (user_id, type, title, message, payload)
    values (
      new.user_id,
      'rank',
      'RANK ADVANCEMENT DETECTED',
      format('Previous Rank: %s. New Rank: %s. Congratulations, Hunter.', v_rank_before, v_rank_after),
      jsonb_build_object('rank_before', v_rank_before, 'rank_after', v_rank_after)
    );
  end if;

  return null;
end;
$$;

create trigger xp_transactions_applied
  after insert on public.xp_transactions
  for each row execute function public.tg_xp_applied();

-- Session completion aggregates + streak.
create or replace function public.tg_session_completed()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tz         text;
  v_today      date;
  v_last       date;
  v_streak     integer;
  v_longest    integer;
begin
  if new.status <> 'completed' or old.status = 'completed' then
    return null;
  end if;

  select coalesce(nullif(timezone, ''), 'UTC'), last_study_date, current_streak, longest_streak
    into v_tz, v_last, v_streak, v_longest
    from public.profiles where id = new.user_id for update;

  update public.profiles
     set total_study_seconds = total_study_seconds + coalesce(new.duration_seconds, 0),
         sessions_completed  = sessions_completed + 1
   where id = new.user_id;

  -- A session of less than one credited minute is recorded but does not
  -- disturb streak bookkeeping.
  if coalesce(new.credited_minutes, 0) > 0 then
    begin
      execute 'select ($1 at time zone $2)::date' into v_today using now(), v_tz;
    exception when others then
      v_today := (now() at time zone 'UTC')::date;
    end;

    if v_last is null then
      v_streak := 1;
    elsif v_last = v_today then
      v_streak := greatest(v_streak, 1);
    elsif v_last = v_today - 1 then
      v_streak := v_streak + 1;
    else
      v_streak := 1;
    end if;

    v_longest := greatest(coalesce(v_longest, 0), v_streak);

    update public.profiles
       set current_streak = v_streak,
           longest_streak = v_longest,
           last_study_date = v_today
     where id = new.user_id;
  end if;

  return null;
end;
$$;

create trigger sessions_completed
  after update on public.study_sessions
  for each row execute function public.tg_session_completed();

create or replace function public.tg_achievement_count()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.profiles
     set achievements_count = achievements_count + 1
   where id = new.user_id;
  return null;
end;
$$;

create trigger user_achievements_count
  after insert on public.user_achievements
  for each row execute function public.tg_achievement_count();

-- New auth user -> Hunter profile.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_username text;
  v_base     text;
  v_tz       text;
  v_try      integer := 0;
begin
  v_username := btrim(coalesce(new.raw_user_meta_data ->> 'username', ''));

  if v_username !~ '^[A-Za-z0-9_]{3,20}$' then
    v_base := 'hunter_' || substr(replace(new.id::text, '-', ''), 1, 8);
    v_username := v_base;
  else
    v_base := v_username;
  end if;

  v_tz := coalesce(nullif(btrim(new.raw_user_meta_data ->> 'timezone'), ''), 'UTC');

  -- Resolve collisions deterministically instead of failing the signup.
  while exists (select 1 from public.profiles where lower(username) = lower(v_username)) loop
    v_try := v_try + 1;
    v_username := left(v_base, 20 - length('_' || v_try::text)) || '_' || v_try::text;
    if v_try > 50 then
      v_username := left('hunter', 13) || '_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);
      exit;
    end if;
  end loop;

  insert into public.profiles (id, username, display_name, timezone)
  values (new.id, v_username, v_username, v_tz)
  on conflict (id) do nothing;

  return null;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ----------------------------------------------------------------------------
-- Rate limiting helper (server-only)
-- ----------------------------------------------------------------------------
create or replace function public.check_rate_limit(p_action text, p_max integer, p_window_seconds integer)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  uuid := auth.uid();
  v_count integer;
begin
  if v_user is null then
    return false;
  end if;

  select count(*) into v_count
    from public.rate_limit_events
   where user_id = v_user
     and action = p_action
     and created_at > now() - make_interval(secs => greatest(p_window_seconds, 1));

  if v_count >= p_max then
    return false;
  end if;

  insert into public.rate_limit_events (user_id, action) values (v_user, p_action);
  return true;
end;
$$;

create or replace function public.username_available(p_username text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select (p_username ~ '^[A-Za-z0-9_]{3,20}$')
    and not exists (select 1 from public.profiles where lower(username) = lower(btrim(p_username)));
$$;


-- ############################################################################
-- ## 0003_engine.sql
-- ############################################################################

-- ============================================================================
-- HUNTER SYSTEM - 0003 SERVER ENGINE (sessions, quests, achievements)
-- ----------------------------------------------------------------------------
-- Every mutation that can create value (time credited, XP, quest rewards,
-- achievements) lives here as a SECURITY DEFINER function. Clients have no
-- write access to xp_transactions / study_sessions / quests at all.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Time accounting
-- ----------------------------------------------------------------------------
create or replace function public.pause_overlap_seconds(p_session uuid, p_from timestamptz, p_to timestamptz)
returns numeric
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    sum(greatest(0, extract(epoch from (
      least(coalesce(p.resumed_at, p_to), p_to) - greatest(p.paused_at, p_from)
    )))),
    0
  )
  from public.study_session_pauses p
  where p.session_id = p_session
    and p.paused_at < p_to
    and coalesce(p.resumed_at, p_to) > p_from;
$$;

-- Credited focus time is derived from server-stamped heartbeats, with each
-- gap clipped to max_heartbeat_gap. A tab left open, a spoofed client timer or
-- a device that slept therefore cannot manufacture credit.
create or replace function public.session_credited_seconds(p_session uuid)
returns table (credited_seconds integer, paused_seconds integer, beat_count integer)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_s        public.study_sessions;
  v_cfg      public.progression_config;
  v_end      timestamptz;
  v_prev     timestamptz;
  v_total    numeric := 0;
  v_gap      numeric;
  v_beat     record;
  v_count    integer := 0;
  v_paused   integer := 0;
begin
  select * into v_s from public.study_sessions where id = p_session;
  if not found then
    return query select 0, 0, 0;
    return;
  end if;

  select * into v_cfg from public.progression_config where id = 1;

  v_end := least(coalesce(v_s.ended_at, now()), now());
  v_end := least(v_end, v_s.started_at + make_interval(secs => v_cfg.max_session_seconds));
  v_prev := v_s.started_at;

  for v_beat in
    select seen_at from public.study_session_heartbeats
     where session_id = p_session and seen_at > v_s.started_at
     order by seen_at
  loop
    continue when v_beat.seen_at > v_end;
    v_count := v_count + 1;
    v_gap := least(extract(epoch from (v_beat.seen_at - v_prev)), v_cfg.max_heartbeat_gap);
    v_total := v_total + v_gap - public.pause_overlap_seconds(p_session, v_prev, v_beat.seen_at);
    v_prev := v_beat.seen_at;
  end loop;

  if v_end > v_prev then
    v_gap := least(extract(epoch from (v_end - v_prev)), v_cfg.max_heartbeat_gap);
    v_total := v_total + v_gap - public.pause_overlap_seconds(p_session, v_prev, v_end);
  end if;

  select coalesce(sum(extract(epoch from (coalesce(p.resumed_at, now()) - p.paused_at))), 0)::integer
    into v_paused
    from public.study_session_pauses p
   where p.session_id = p_session;

  return query select greatest(0, round(v_total)::integer), greatest(v_paused, 0), v_count;
end;
$$;

create or replace function public.hunter_day_start(p_user uuid, p_at timestamptz default now())
returns timestamptz
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_tz    text;
  v_today date;
begin
  select coalesce(nullif(timezone, ''), 'UTC') into v_tz from public.profiles where id = p_user;
  v_tz := coalesce(v_tz, 'UTC');
  begin
    execute 'select ($1 at time zone $2)::date' into v_today using p_at, v_tz;
    return (v_today::timestamp at time zone v_tz);
  exception when others then
    return (date_trunc('day', p_at at time zone 'UTC') at time zone 'UTC');
  end;
end;
$$;

-- ----------------------------------------------------------------------------
-- Session lifecycle
-- ----------------------------------------------------------------------------
create or replace function public.start_study_session(
  p_planned_seconds integer,
  p_client_token    uuid,
  p_subject_id      uuid default null,
  p_topic_id        uuid default null,
  p_is_revision     boolean default false,
  p_note            text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  uuid := auth.uid();
  v_cfg   public.progression_config;
  v_row   public.study_sessions;
  v_max   integer;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  select * into v_cfg from public.progression_config where id = 1;
  v_max := least(43200, v_cfg.max_session_seconds);

  if p_planned_seconds is null or p_planned_seconds < 60 or p_planned_seconds > v_max then
    raise exception 'INVALID_PLANNED_DURATION' using errcode = '22023';
  end if;

  if p_client_token is null then
    raise exception 'MISSING_CLIENT_TOKEN' using errcode = '22023';
  end if;

  -- Idempotent: retrying the same start returns the same session.
  select * into v_row
    from public.study_sessions
   where user_id = v_user and client_token = p_client_token;
  if found then
    return jsonb_build_object('session', to_jsonb(v_row), 'reused', true);
  end if;

  if not public.check_rate_limit('start_session', 40, 3600) then
    raise exception 'RATE_LIMITED' using errcode = '53400';
  end if;

  if p_subject_id is not null and not exists (
    select 1 from public.subjects where id = p_subject_id and user_id = v_user
  ) then
    raise exception 'INVALID_SUBJECT' using errcode = '22023';
  end if;

  if p_topic_id is not null and not exists (
    select 1 from public.topics where id = p_topic_id and user_id = v_user
  ) then
    raise exception 'INVALID_TOPIC' using errcode = '22023';
  end if;

  -- Abandoned sessions stop blocking the hunter.
  update public.study_sessions
     set status = 'cancelled',
         ended_at = greatest(coalesce(ended_at, now()), started_at)
   where user_id = v_user
     and status in ('active', 'paused')
     and started_at < now() - make_interval(secs => v_max);

  if exists (
    select 1 from public.study_sessions
     where user_id = v_user and status in ('active', 'paused')
  ) then
    raise exception 'SESSION_ALREADY_ACTIVE' using errcode = '23505';
  end if;

  insert into public.study_sessions
    (user_id, subject_id, topic_id, client_token, planned_seconds, is_revision, note)
  values
    (v_user, p_subject_id, p_topic_id, p_client_token, p_planned_seconds,
     coalesce(p_is_revision, false), nullif(btrim(coalesce(p_note, '')), ''))
  returning * into v_row;

  insert into public.study_session_heartbeats (session_id, user_id) values (v_row.id, v_user);

  return jsonb_build_object('session', to_jsonb(v_row), 'reused', false);
end;
$$;

create or replace function public.heartbeat_study_session(p_session uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_row  public.study_sessions;
  v_acc  record;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  select * into v_row from public.study_sessions where id = p_session and user_id = v_user;
  if not found then
    raise exception 'SESSION_NOT_FOUND' using errcode = '22023';
  end if;

  if v_row.status not in ('active', 'paused') then
    return jsonb_build_object('status', v_row.status, 'live', false);
  end if;

  if v_row.status = 'active' then
    if not public.check_rate_limit('heartbeat', 12, 60) then
      return jsonb_build_object('status', v_row.status, 'live', true, 'throttled', true);
    end if;
    insert into public.study_session_heartbeats (session_id, user_id) values (v_row.id, v_user);
  end if;

  select * into v_acc from public.session_credited_seconds(p_session);

  return jsonb_build_object(
    'status', v_row.status,
    'live', true,
    'credited_seconds', v_acc.credited_seconds,
    'paused_seconds', v_acc.paused_seconds
  );
end;
$$;

create or replace function public.pause_study_session(p_session uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_row  public.study_sessions;
  v_acc  record;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  select * into v_row from public.study_sessions where id = p_session and user_id = v_user for update;
  if not found then
    raise exception 'SESSION_NOT_FOUND' using errcode = '22023';
  end if;

  if v_row.status = 'paused' then
    select * into v_acc from public.session_credited_seconds(p_session);
    return jsonb_build_object('status', 'paused', 'credited_seconds', v_acc.credited_seconds);
  end if;

  if v_row.status <> 'active' then
    raise exception 'SESSION_NOT_ACTIVE' using errcode = '22023';
  end if;

  insert into public.study_session_pauses (session_id, user_id)
  values (v_row.id, v_user)
  on conflict do nothing;

  update public.study_sessions set status = 'paused' where id = v_row.id;

  select * into v_acc from public.session_credited_seconds(p_session);
  return jsonb_build_object('status', 'paused', 'credited_seconds', v_acc.credited_seconds);
end;
$$;

create or replace function public.resume_study_session(p_session uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_row  public.study_sessions;
  v_acc  record;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  select * into v_row from public.study_sessions where id = p_session and user_id = v_user for update;
  if not found then
    raise exception 'SESSION_NOT_FOUND' using errcode = '22023';
  end if;

  if v_row.status = 'active' then
    return jsonb_build_object('status', 'active');
  end if;
  if v_row.status <> 'paused' then
    raise exception 'SESSION_NOT_PAUSED' using errcode = '22023';
  end if;

  update public.study_session_pauses
     set resumed_at = now()
   where session_id = v_row.id and resumed_at is null;

  update public.study_sessions set status = 'active' where id = v_row.id;
  insert into public.study_session_heartbeats (session_id, user_id) values (v_row.id, v_user);

  select * into v_acc from public.session_credited_seconds(p_session);
  return jsonb_build_object('status', 'active', 'credited_seconds', v_acc.credited_seconds);
end;
$$;

create or replace function public.cancel_study_session(p_session uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_row  public.study_sessions;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  select * into v_row from public.study_sessions where id = p_session and user_id = v_user for update;
  if not found then
    raise exception 'SESSION_NOT_FOUND' using errcode = '22023';
  end if;

  if v_row.status = 'completed' then
    raise exception 'SESSION_ALREADY_COMPLETED' using errcode = '22023';
  end if;

  update public.study_session_pauses
     set resumed_at = now()
   where session_id = v_row.id and resumed_at is null;

  update public.study_sessions
     set status = 'cancelled', ended_at = coalesce(ended_at, now())
   where id = v_row.id;

  return jsonb_build_object('status', 'cancelled');
end;
$$;

-- ----------------------------------------------------------------------------
-- Quests
-- ----------------------------------------------------------------------------
create or replace function public.ensure_quests(p_user uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tz      text;
  v_today   date;
  v_day     timestamptz;
  v_week    timestamptz;
  v_tpl     public.quest_templates;
  v_started timestamptz;
begin
  select coalesce(nullif(timezone, ''), 'UTC'), created_at into v_tz, v_started
    from public.profiles where id = p_user;
  if not found then
    return;
  end if;

  begin
    execute 'select (now() at time zone $1)::date' into v_today using v_tz;
    v_day := v_today::timestamp at time zone v_tz;
    v_week := (date_trunc('week', v_today::timestamp)) at time zone v_tz;
  exception when others then
    v_tz := 'UTC';
    v_today := (now() at time zone 'UTC')::date;
    v_day := date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
    v_week := date_trunc('week', now() at time zone 'UTC') at time zone 'UTC';
  end;

  for v_tpl in select * from public.quest_templates loop
    if v_tpl.recurrence = 'daily' then
      insert into public.quests (user_id, template_code, title, description, category, difficulty,
                                 metric, target_value, reward_xp, period_key, starts_at, ends_at)
      values (p_user, v_tpl.code, v_tpl.title, v_tpl.description, v_tpl.category, v_tpl.difficulty,
              v_tpl.metric, v_tpl.target_value, v_tpl.reward_xp,
              to_char(v_today, 'YYYY-MM-DD'), v_day, v_day + interval '1 day')
      on conflict (user_id, template_code, period_key) do nothing;

    elsif v_tpl.recurrence = 'weekly' then
      insert into public.quests (user_id, template_code, title, description, category, difficulty,
                                 metric, target_value, reward_xp, period_key, starts_at, ends_at)
      values (p_user, v_tpl.code, v_tpl.title, v_tpl.description, v_tpl.category, v_tpl.difficulty,
              v_tpl.metric, v_tpl.target_value, v_tpl.reward_xp,
              to_char(v_today, 'IYYY-IW'), v_week, v_week + interval '7 days')
      on conflict (user_id, template_code, period_key) do nothing;

    else
      insert into public.quests (user_id, template_code, title, description, category, difficulty,
                                 metric, target_value, reward_xp, period_key, starts_at, ends_at)
      values (p_user, v_tpl.code, v_tpl.title, v_tpl.description, v_tpl.category, v_tpl.difficulty,
              v_tpl.metric, v_tpl.target_value, v_tpl.reward_xp,
              'once', v_started, now() + interval '100 years')
      on conflict (user_id, template_code, period_key) do nothing;
    end if;
  end loop;
end;
$$;

create or replace function public.evaluate_quests(p_user uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_quest   public.quests;
  v_value   numeric;
  v_done    jsonb := '[]'::jsonb;
begin
  -- Expire anything whose window closed.
  update public.quests
     set status = 'expired'
   where user_id = p_user and status = 'active' and ends_at <= now();

  for v_quest in
    select * from public.quests
     where user_id = p_user and status = 'active' and ends_at > now()
     order by created_at, title
  loop
    v_value := public.hunter_metric(v_quest.metric, p_user, now());

    update public.quests
       set progress_value = v_value
     where id = v_quest.id;

    if v_value >= v_quest.target_value then
      update public.quests
         set status = 'completed', completed_at = now(), progress_value = v_quest.target_value
       where id = v_quest.id and status = 'active';

      if found then
        insert into public.xp_transactions (user_id, source_type, source_id, amount, detail)
        values (p_user, 'quest', v_quest.id, v_quest.reward_xp,
                jsonb_build_object('quest', v_quest.template_code, 'title', v_quest.title))
        on conflict do nothing;

        update public.profiles
           set quests_completed = quests_completed + 1
         where id = p_user;

        insert into public.notifications (user_id, type, title, message, payload)
        values (p_user, 'quest', 'QUEST COMPLETED', v_quest.title,
                jsonb_build_object('quest_id', v_quest.id, 'reward_xp', v_quest.reward_xp,
                                   'category', v_quest.category));

        v_done := v_done || jsonb_build_array(jsonb_build_object(
          'id', v_quest.id,
          'title', v_quest.title,
          'category', v_quest.category,
          'reward_xp', v_quest.reward_xp
        ));
      end if;
    end if;
  end loop;

  return v_done;
end;
$$;

-- ----------------------------------------------------------------------------
-- Achievements
-- ----------------------------------------------------------------------------
create or replace function public.evaluate_achievements(p_user uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_ach     public.achievements;
  v_value   numeric;
  v_row_id  uuid;
  v_unlock  jsonb := '[]'::jsonb;
begin
  for v_ach in
    select a.* from public.achievements a
     where not exists (
       select 1 from public.user_achievements ua
        where ua.user_id = p_user and ua.achievement_code = a.code
     )
     order by a.sort_order
  loop
    v_value := public.hunter_metric(v_ach.metric, p_user, now());
    continue when v_value < v_ach.target_value;

    insert into public.user_achievements (user_id, achievement_code)
    values (p_user, v_ach.code)
    on conflict (user_id, achievement_code) do nothing
    returning id into v_row_id;

    continue when v_row_id is null;

    if v_ach.reward_xp > 0 then
      insert into public.xp_transactions (user_id, source_type, source_id, amount, detail)
      values (p_user, 'achievement', v_row_id, v_ach.reward_xp,
              jsonb_build_object('achievement', v_ach.code, 'name', v_ach.name))
      on conflict do nothing;
    end if;

    insert into public.notifications (user_id, type, title, message, payload)
    values (p_user, 'achievement', 'ACHIEVEMENT UNLOCKED', v_ach.name,
            jsonb_build_object('achievement', v_ach.code, 'rarity', v_ach.rarity,
                               'reward_xp', v_ach.reward_xp));

    v_unlock := v_unlock || jsonb_build_array(jsonb_build_object(
      'code', v_ach.code,
      'name', v_ach.name,
      'description', v_ach.description,
      'icon', v_ach.icon,
      'rarity', v_ach.rarity,
      'reward_xp', v_ach.reward_xp
    ));
  end loop;

  return v_unlock;
end;
$$;

-- Public entry point used by the app when a page needs fresh quest progress.
create or replace function public.refresh_quests()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_done jsonb;
  v_unlock jsonb;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  perform public.ensure_quests(v_user);
  v_done := public.evaluate_quests(v_user);
  v_unlock := public.evaluate_achievements(v_user);

  return jsonb_build_object('completed_quests', v_done, 'unlocked_achievements', v_unlock);
end;
$$;

-- ----------------------------------------------------------------------------
-- Complete a session — the single XP-awarding path for study time
-- ----------------------------------------------------------------------------
create or replace function public.complete_study_session(p_session uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user        uuid := auth.uid();
  v_s           public.study_sessions;
  v_cfg         public.progression_config;
  v_acc         record;
  v_minutes     integer := 0;
  v_xp_intent   integer := 0;
  v_xp_granted  integer := 0;
  v_day_start   timestamptz;
  v_day_used    integer := 0;
  v_remaining   integer;
  v_level_bf    integer;
  v_rank_bf     text;
  v_level_af    integer;
  v_rank_af     text;
  v_quests      jsonb := '[]'::jsonb;
  v_unlocked    jsonb := '[]'::jsonb;
  v_streak      integer := 0;
  v_already     boolean := false;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  select * into v_s
    from public.study_sessions
   where id = p_session and user_id = v_user
   for update;

  if not found then
    raise exception 'SESSION_NOT_FOUND' using errcode = '22023';
  end if;

  select * into v_cfg from public.progression_config where id = 1;

  -- Replay protection: completing twice never pays twice.
  if v_s.status = 'completed' then
    select * into v_acc from public.session_credited_seconds(p_session);
    select level, rank into v_level_af, v_rank_af from public.profiles where id = v_user;
    return jsonb_build_object(
      'already_completed', true,
      'session', to_jsonb(v_s),
      'xp_awarded', v_s.xp_awarded,
      'credited_minutes', coalesce(v_s.credited_minutes, 0),
      'credited_seconds', v_acc.credited_seconds,
      'level', v_level_af,
      'rank', v_rank_af,
      'completed_quests', v_quests,
      'unlocked_achievements', v_unlocked
    );
  end if;

  if v_s.status = 'cancelled' then
    raise exception 'SESSION_CANCELLED' using errcode = '22023';
  end if;

  select level, rank into v_level_bf, v_rank_bf from public.profiles where id = v_user;

  -- Seal the session: close any open pause, stamp the end, derive credit.
  update public.study_session_pauses
     set resumed_at = now()
   where session_id = p_session and resumed_at is null;

  update public.study_sessions
     set ended_at = now()
   where id = p_session and ended_at is null;

  select * into v_s from public.study_sessions where id = p_session;
  select * into v_acc from public.session_credited_seconds(p_session);

  v_minutes := floor(v_acc.credited_seconds / 60.0)::integer;

  if v_minutes > 0 then
    v_xp_intent := v_minutes * v_cfg.xp_per_minute;

    -- Daily reward cap: study time is still recorded past the cap, XP is not.
    v_day_start := public.hunter_day_start(v_user, now());
    select coalesce(sum(amount), 0) into v_day_used
      from public.xp_transactions
     where user_id = v_user
       and source_type = 'session'
       and created_at >= v_day_start;

    v_remaining := greatest(v_cfg.daily_xp_cap - v_day_used, 0);
    v_xp_granted := least(v_xp_intent, v_remaining);
  end if;

  update public.study_sessions
     set status = 'completed',
         duration_seconds = v_acc.credited_seconds,
         paused_seconds = v_acc.paused_seconds,
         credited_minutes = v_minutes,
         xp_awarded = v_xp_granted,
         ended_at = coalesce(ended_at, now())
   where id = p_session;

  if v_xp_granted > 0 then
    insert into public.xp_transactions (user_id, source_type, source_id, amount, detail)
    values (v_user, 'session', p_session, v_xp_granted,
            jsonb_build_object(
              'minutes', v_minutes,
              'subject_id', v_s.subject_id,
              'intent', v_xp_intent,
              'capped', v_xp_intent > v_xp_granted
            ))
    on conflict do nothing;
  end if;

  if v_minutes > 0 then
    insert into public.notifications (user_id, type, title, message, payload)
    values (v_user, 'session', 'SESSION RECORDED',
            format('%s minutes of focused study. %s', v_minutes,
                   case when v_xp_granted > 0 then format('+%s XP.', v_xp_granted)
                        else 'Daily XP cap reached — time recorded.' end),
            jsonb_build_object('session_id', p_session, 'minutes', v_minutes,
                               'xp', v_xp_granted));
  end if;

  -- Topic revision bookkeeping
  if v_s.topic_id is not null and v_minutes > 0 then
    update public.topics
       set revision_count = revision_count + case when v_s.is_revision then 1 else 0 end,
           last_revised_at = case when v_s.is_revision then now() else last_revised_at end,
           status = case
                      when v_s.is_revision and status in ('not_started', 'learning') then 'revised'::public.topic_status
                      else status
                    end
     where id = v_s.topic_id and user_id = v_user;
  end if;

  perform public.ensure_quests(v_user);
  v_quests := public.evaluate_quests(v_user);
  v_unlocked := public.evaluate_achievements(v_user);

  select level, rank, current_streak into v_level_af, v_rank_af, v_streak
    from public.profiles where id = v_user;

  select * into v_s from public.study_sessions where id = p_session;

  return jsonb_build_object(
    'already_completed', v_already,
    'session', to_jsonb(v_s),
    'xp_awarded', v_xp_granted,
    'xp_intent', v_xp_intent,
    'capped', v_xp_intent > v_xp_granted,
    'credited_minutes', v_minutes,
    'credited_seconds', v_acc.credited_seconds,
    'voided', v_minutes = 0,
    'level', v_level_af,
    'level_before', v_level_bf,
    'level_up', v_level_af > v_level_bf,
    'rank', v_rank_af,
    'rank_before', v_rank_bf,
    'rank_up', public.rank_index(v_rank_af) > public.rank_index(v_rank_bf),
    'streak', v_streak,
    'completed_quests', v_quests,
    'unlocked_achievements', v_unlocked
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- Profile / account management (no direct table writes for clients)
-- ----------------------------------------------------------------------------
create or replace function public.update_my_profile(
  p_username            text default null,
  p_display_name        text default null,
  p_bio                 text default null,
  p_avatar_url          text default null,
  p_timezone            text default null,
  p_is_public           boolean default null,
  p_show_on_leaderboard boolean default null,
  p_daily_goal_minutes  integer default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_name text;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  if p_username is not null and btrim(p_username) <> '' then
    v_name := btrim(p_username);
    if v_name !~ '^[A-Za-z0-9_]{3,20}$' then
      raise exception 'INVALID_USERNAME' using errcode = '22023';
    end if;
    if exists (
      select 1 from public.profiles
       where lower(username) = lower(v_name) and id <> v_user
    ) then
      raise exception 'USERNAME_TAKEN' using errcode = '23505';
    end if;
  end if;

  if p_daily_goal_minutes is not null
     and (p_daily_goal_minutes < 15 or p_daily_goal_minutes > 1440) then
    raise exception 'INVALID_DAILY_GOAL' using errcode = '22023';
  end if;

  update public.profiles
     set username = coalesce(v_name, username),
         display_name = case when p_display_name is null then display_name
                             else nullif(btrim(p_display_name), '') end,
         bio = case when p_bio is null then bio
                    else nullif(btrim(p_bio), '') end,
         avatar_url = case when p_avatar_url is null then avatar_url
                           else nullif(btrim(p_avatar_url), '') end,
         timezone = coalesce(nullif(btrim(p_timezone), ''), timezone),
         is_public = coalesce(p_is_public, is_public),
         show_on_leaderboard = coalesce(p_show_on_leaderboard, show_on_leaderboard),
         daily_goal_minutes = coalesce(p_daily_goal_minutes, daily_goal_minutes)
   where id = v_user;

  return (select to_jsonb(p) from public.profiles p where p.id = v_user);
end;
$$;

create or replace function public.mark_awakened()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_row  public.profiles;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  update public.profiles
     set awakened_at = coalesce(awakened_at, now())
   where id = v_user;

  select * into v_row from public.profiles where id = v_user;
  return jsonb_build_object('awakened_at', v_row.awakened_at);
end;
$$;

create or replace function public.mark_notifications_read(p_ids uuid[] default null)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_count integer;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  update public.notifications
     set is_read = true
   where user_id = v_user
     and not is_read
     and (p_ids is null or id = any (p_ids));

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

create or replace function public.delete_my_account()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  -- Cascades through profiles and every user-owned table.
  delete from auth.users where id = v_user;
  return jsonb_build_object('deleted', true);
end;
$$;


-- ############################################################################
-- ## 0004_rls.sql
-- ############################################################################

-- ============================================================================
-- HUNTER SYSTEM - 0004 ROW LEVEL SECURITY + PRIVILEGES
-- ----------------------------------------------------------------------------
-- Principle: clients may READ what they own (plus clearly public catalog data)
-- and may WRITE only their own subjects/topics. Every value-bearing write
-- (XP, sessions, quests, achievements, profile progression) goes through the
-- SECURITY DEFINER functions in migration 0003.
-- ============================================================================

alter table public.profiles                enable row level security;
alter table public.subjects                enable row level security;
alter table public.topics                  enable row level security;
alter table public.study_sessions          enable row level security;
alter table public.study_session_pauses    enable row level security;
alter table public.study_session_heartbeats enable row level security;
alter table public.xp_transactions         enable row level security;
alter table public.quest_templates         enable row level security;
alter table public.quests                  enable row level security;
alter table public.achievements            enable row level security;
alter table public.user_achievements       enable row level security;
alter table public.notifications           enable row level security;
alter table public.rate_limit_events       enable row level security;
alter table public.progression_config      enable row level security;
alter table public.rank_thresholds         enable row level security;

-- ----------------------------------------------------------------------------
-- Strip the default Supabase grants, then hand back only what is needed.
-- ----------------------------------------------------------------------------
revoke all on all tables in schema public from anon, authenticated;

grant select on public.profiles            to anon, authenticated;
grant select on public.rank_thresholds     to anon, authenticated;
grant select on public.progression_config  to anon, authenticated;
grant select on public.achievements        to anon, authenticated;
grant select on public.quest_templates     to anon, authenticated;

grant select, insert, update, delete on public.subjects to authenticated;
grant select, insert, update, delete on public.topics   to authenticated;

grant select on public.study_sessions           to authenticated;
grant select on public.study_session_pauses     to authenticated;
grant select on public.study_session_heartbeats to authenticated;
grant select on public.xp_transactions          to authenticated;
grant select on public.quests                   to authenticated;
grant select on public.user_achievements        to authenticated;
grant select on public.notifications            to authenticated;

-- rate_limit_events: service role only (no grants).

-- ----------------------------------------------------------------------------
-- Policies
-- ----------------------------------------------------------------------------
create policy profiles_read_self_or_public on public.profiles
  for select to authenticated
  using (id = auth.uid() or is_public);

create policy profiles_read_public on public.profiles
  for select to anon
  using (is_public);

create policy subjects_owner_all on public.subjects
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create policy topics_owner_all on public.topics
  for all to authenticated
  using (user_id = auth.uid())
  with check (
    user_id = auth.uid()
    and exists (
      select 1 from public.subjects s
       where s.id = topics.subject_id and s.user_id = auth.uid()
    )
  );

create policy sessions_read_own on public.study_sessions
  for select to authenticated using (user_id = auth.uid());

create policy pauses_read_own on public.study_session_pauses
  for select to authenticated using (user_id = auth.uid());

create policy heartbeats_read_own on public.study_session_heartbeats
  for select to authenticated using (user_id = auth.uid());

create policy xp_read_own on public.xp_transactions
  for select to authenticated using (user_id = auth.uid());

create policy quests_read_own on public.quests
  for select to authenticated using (user_id = auth.uid());

create policy achievements_read_own on public.user_achievements
  for select to authenticated using (user_id = auth.uid());

create policy notifications_read_own on public.notifications
  for select to authenticated using (user_id = auth.uid());

create policy quest_templates_public on public.quest_templates
  for select to anon, authenticated using (true);

create policy achievements_catalog_public on public.achievements
  for select to anon, authenticated using (true);

create policy rank_thresholds_public on public.rank_thresholds
  for select to anon, authenticated using (true);

create policy progression_config_public on public.progression_config
  for select to anon, authenticated using (true);

-- ----------------------------------------------------------------------------
-- Function privileges: default PUBLIC execute is revoked, then re-granted
-- per role. Internal helpers stay unreachable from the anon key.
-- ----------------------------------------------------------------------------
do $$
declare
  v_fn text;
begin
  for v_fn in
    select string_agg(p.oid::regprocedure::text, ',')
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
     group by p.proname
  loop
    execute format('revoke all on function %s from public', v_fn);
  end loop;
end;
$$;

-- Read-only helpers anyone may call.
grant execute on function public.level_for_xp(bigint) to anon, authenticated;
grant execute on function public.level_for_xp(bigint, integer, integer) to anon, authenticated;
grant execute on function public.xp_to_reach_level(integer, integer, integer) to anon, authenticated;
grant execute on function public.level_step_xp(integer, integer, integer) to anon, authenticated;
grant execute on function public.rank_for_xp(bigint) to anon, authenticated;
grant execute on function public.rank_index(text) to anon, authenticated;
grant execute on function public.level_progress(bigint) to anon, authenticated;
grant execute on function public.hunter_progression() to anon, authenticated;
grant execute on function public.username_available(text) to anon, authenticated;

-- Authenticated gameplay surface.
grant execute on function public.start_study_session(integer, uuid, uuid, uuid, boolean, text) to authenticated;
grant execute on function public.heartbeat_study_session(uuid) to authenticated;
grant execute on function public.pause_study_session(uuid) to authenticated;
grant execute on function public.resume_study_session(uuid) to authenticated;
grant execute on function public.cancel_study_session(uuid) to authenticated;
grant execute on function public.complete_study_session(uuid) to authenticated;
grant execute on function public.refresh_quests() to authenticated;
grant execute on function public.update_my_profile(text, text, text, text, text, boolean, boolean, integer) to authenticated;
grant execute on function public.mark_awakened() to authenticated;
grant execute on function public.mark_notifications_read(uuid[]) to authenticated;
grant execute on function public.delete_my_account() to authenticated;
grant execute on function public.hunter_metric(text, uuid, timestamptz) to authenticated;
grant execute on function public.session_credited_seconds(uuid) to authenticated;
grant execute on function public.hunter_day_start(uuid, timestamptz) to authenticated;


-- ############################################################################
-- ## 0005_leaderboard.sql
-- ############################################################################

-- ============================================================================
-- HUNTER SYSTEM - 0005 LEADERBOARD + PUBLIC PROFILE
-- ----------------------------------------------------------------------------
-- All ranking happens in the database so the client can never invent a score.
-- Tie-breaking is deterministic: period XP desc, lifetime XP desc, seniority.
-- ============================================================================

create or replace function public.leaderboard_period_start(p_period text)
returns timestamptz
language sql
stable
as $$
  select case lower(coalesce(p_period, 'all'))
           when 'week'  then date_trunc('week', now())
           when 'month' then date_trunc('month', now())
           else null
         end;
$$;

create or replace function public.leaderboard(
  p_period text default 'all',
  p_limit  integer default 25,
  p_offset integer default 0,
  p_search text default null
)
returns table (
  rank_position bigint,
  user_id      uuid,
  username     text,
  display_name text,
  avatar_url   text,
  hunter_rank  text,
  level        integer,
  period_xp    bigint,
  is_me        boolean
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with v as (
    select public.leaderboard_period_start(p_period) as period_start
  ),
  scored as (
    select p.id,
           p.username,
           coalesce(p.display_name, p.username) as display_name,
           p.avatar_url,
           p.rank::text as hunter_rank,
           p.level,
           p.created_at,
           p.xp_total,
           case
             when v.period_start is null then p.xp_total
             else coalesce((
               select sum(t.amount)::bigint
                 from public.xp_transactions t
                where t.user_id = p.id and t.created_at >= v.period_start
             ), 0)
           end as period_xp
      from public.profiles p
      cross join v
     where p.is_public
       and p.show_on_leaderboard
       and (p_search is null or btrim(p_search) = '' or p.username ilike '%' || btrim(p_search) || '%')
  ),
  filtered as (
    select s.* from scored s, v
     where v.period_start is null or s.period_xp > 0
  ),
  ranked as (
    select f.*,
           row_number() over (
             order by f.period_xp desc, f.xp_total desc, f.created_at asc, f.id asc
           ) as pos
      from filtered f
  )
  select r.pos,
         r.id,
         r.username,
         r.display_name,
         r.avatar_url,
         r.hunter_rank,
         r.level,
         r.period_xp,
         r.id = auth.uid()
    from ranked r
   order by r.pos
   limit greatest(1, least(coalesce(p_limit, 25), 100))
  offset greatest(coalesce(p_offset, 0), 0);
$$;

create or replace function public.leaderboard_size(
  p_period text default 'all',
  p_search text default null
)
returns bigint
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with v as (
    select public.leaderboard_period_start(p_period) as period_start
  ),
  scored as (
    select p.id, p.xp_total,
           case
             when v.period_start is null then p.xp_total
             else coalesce((
               select sum(t.amount)::bigint
                 from public.xp_transactions t
                where t.user_id = p.id and t.created_at >= v.period_start
             ), 0)
           end as period_xp
      from public.profiles p
      cross join v
     where p.is_public
       and p.show_on_leaderboard
       and (p_search is null or btrim(p_search) = '' or p.username ilike '%' || btrim(p_search) || '%')
  )
  select count(*)::bigint
    from scored s, v
   where v.period_start is null or s.period_xp > 0;
$$;

-- Where the signed-in hunter stands right now (null position when opted out
-- or when they have no XP in the selected window).
create or replace function public.my_leaderboard_standing(p_period text default 'all')
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with me as (
    select id, xp_total, is_public, show_on_leaderboard from public.profiles where id = auth.uid()
  ),
  v as (
    select public.leaderboard_period_start(p_period) as period_start
  ),
  scored as (
    select p.id, p.xp_total, p.created_at,
           case
             when v.period_start is null then p.xp_total
             else coalesce((
               select sum(t.amount)::bigint
                 from public.xp_transactions t
                where t.user_id = p.id and t.created_at >= v.period_start
             ), 0)
           end as period_xp
      from public.profiles p
      cross join v
     where p.is_public and p.show_on_leaderboard
  ),
  filtered as (
    select s.* from scored s, v where v.period_start is null or s.period_xp > 0
  ),
  ranked as (
    select f.*, row_number() over (
      order by f.period_xp desc, f.xp_total desc, f.created_at asc, f.id asc
    ) as pos from filtered f
  )
  select jsonb_build_object(
    'listed', coalesce((select (me.is_public and me.show_on_leaderboard) from me), false),
    'position', (select r.pos from ranked r, me where r.id = me.id),
    'period_xp', (select r.period_xp from ranked r, me where r.id = me.id),
    'total', (select count(*) from ranked)
  );
$$;

-- ----------------------------------------------------------------------------
-- Public Hunter profile. Returns nothing for private hunters so the UI can
-- show a neutral "profile is private" state without leaking existence data
-- beyond the username check.
-- ----------------------------------------------------------------------------
create or replace function public.public_hunter_profile(p_username text)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with target as (
    select * from public.profiles
     where lower(username) = lower(btrim(p_username))
       and is_public
     limit 1
  ),
  weekly as (
    select count(*)::int as sessions,
           coalesce(sum(s.credited_minutes), 0)::int as minutes
      from public.study_sessions s, target t
     where s.user_id = t.id
       and s.status = 'completed'
       and s.started_at >= date_trunc('week', now())
  ),
  total as (
    select count(*)::int as sessions,
           coalesce(sum(s.credited_minutes), 0)::int as minutes
      from public.study_sessions s, target t
     where s.user_id = t.id
       and s.status = 'completed'
  ),
  badges as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'code', a.code, 'name', a.name, 'description', a.description,
             'icon', a.icon, 'rarity', a.rarity, 'unlocked_at', ua.unlocked_at
           ) order by ua.unlocked_at desc), '[]'::jsonb) as items
      from public.user_achievements ua
      join public.achievements a on a.code = ua.achievement_code
      join target t on t.id = ua.user_id
  ),
  leaderboard_pos as (
    select (select r.pos from (
              select p.id, row_number() over (
                order by p.xp_total desc, p.created_at asc, p.id asc
              ) as pos from public.profiles p
              where p.is_public and p.show_on_leaderboard
            ) r where r.id = t.id) as pos
      from target t
  )
  select case when t.id is null then null else jsonb_build_object(
    'id', t.id,
    'hunter_id', t.hunter_id,
    'username', t.username,
    'display_name', coalesce(t.display_name, t.username),
    'avatar_url', t.avatar_url,
    'bio', t.bio,
    'rank', t.rank,
    'level', t.level,
    'xp_total', t.xp_total,
    'total_study_seconds', t.total_study_seconds,
    'sessions_completed', t.sessions_completed,
    'quests_completed', t.quests_completed,
    'achievements_count', t.achievements_count,
    'current_streak', t.current_streak,
    'longest_streak', t.longest_streak,
    'last_study_date', t.last_study_date,
    'created_at', t.created_at,
    'on_leaderboard', t.show_on_leaderboard,
    'position', (select pos from leaderboard_pos),
    'weekly_sessions', (select sessions from weekly),
    'weekly_minutes', (select minutes from weekly),
    'lifetime_sessions', (select sessions from total),
    'lifetime_minutes', (select minutes from total),
    'achievements', (select items from badges)
  ) end
  from (select * from target) t;
$$;

grant execute on function public.leaderboard_period_start(text) to anon, authenticated;
grant execute on function public.leaderboard(text, integer, integer, text) to anon, authenticated;
grant execute on function public.leaderboard_size(text, text) to anon, authenticated;
grant execute on function public.my_leaderboard_standing(text) to authenticated;
grant execute on function public.public_hunter_profile(text) to anon, authenticated;


