-- ############################################################################
-- ## 0007_analytics.sql
-- ############################################################################

-- ============================================================================
-- HUNTER SYSTEM - 0007 ANALYTICS READ MODELS
-- ----------------------------------------------------------------------------
-- Aggregation happens in PostgreSQL so pages never download a hunter's whole
-- history to add numbers up in JavaScript. Every function is scoped to
-- auth.uid() and returns only that hunter's data.
-- ============================================================================

create or replace function public.hunter_overview()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_user      uuid := auth.uid();
  v_p         public.profiles;
  v_cfg       public.progression_config;
  v_tz        text;
  v_today     date;
  v_day       timestamptz;
  v_week      timestamptz;
  v_month     timestamptz;
  v_lvl       record;
  v_rank_next text;
  v_rank_need bigint;
  v_rank_span bigint;
  v_rank_min  bigint;
  v_next_min  bigint;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  select * into v_p from public.profiles where id = v_user;
  if not found then
    return null;
  end if;

  select * into v_cfg from public.progression_config where id = 1;

  v_tz := coalesce(nullif(v_p.timezone, ''), 'UTC');
  begin
    execute 'select (now() at time zone $1)::date' into v_today using v_tz;
    v_day := v_today::timestamp at time zone v_tz;
    v_week := (date_trunc('week', v_today::timestamp)) at time zone v_tz;
    v_month := (date_trunc('month', v_today::timestamp)) at time zone v_tz;
  exception when others then
    v_tz := 'UTC';
    v_today := (now() at time zone 'UTC')::date;
    v_day := date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
    v_week := date_trunc('week', now() at time zone 'UTC') at time zone 'UTC';
    v_month := date_trunc('month', now() at time zone 'UTC') at time zone 'UTC';
  end;

  select * into v_lvl from public.level_progress(v_p.xp_total);

  select min_xp into v_rank_min from public.rank_thresholds where rank = v_p.rank;
  select t.rank, t.min_xp into v_rank_next, v_next_min
    from public.rank_thresholds t
   where t.order_index = public.rank_index(v_p.rank) + 1;

  v_rank_span := coalesce(v_next_min - v_rank_min, 1);
  v_rank_need := greatest(coalesce(v_next_min - v_p.xp_total, 0), 0);

  return jsonb_build_object(
    'profile', to_jsonb(v_p),
    'level', jsonb_build_object(
      'level', v_lvl.level,
      'into', v_lvl.into_level,
      'needed', v_lvl.needed,
      'percent', v_lvl.percent,
      'next_at', v_lvl.level_xp_next
    ),
    'rank', jsonb_build_object(
      'rank', v_p.rank,
      'next', v_rank_next,
      'remaining', v_rank_need,
      'percent', case
                   when v_rank_next is null then 100
                   else round(((v_p.xp_total - v_rank_min)::numeric / v_rank_span::numeric) * 100, 2)
                 end
    ),
    'today', jsonb_build_object(
      'minutes', (select coalesce(sum(credited_minutes), 0) from public.study_sessions
                   where user_id = v_user and status = 'completed' and started_at >= v_day),
      'sessions', (select count(*) from public.study_sessions
                    where user_id = v_user and status = 'completed' and started_at >= v_day
                      and coalesce(credited_minutes, 0) > 0),
      'xp', (select coalesce(sum(amount), 0) from public.xp_transactions
              where user_id = v_user and created_at >= v_day),
      'goal', v_p.daily_goal_minutes
    ),
    'week', jsonb_build_object(
      'minutes', (select coalesce(sum(credited_minutes), 0) from public.study_sessions
                   where user_id = v_user and status = 'completed' and started_at >= v_week),
      'sessions', (select count(*) from public.study_sessions
                    where user_id = v_user and status = 'completed' and started_at >= v_week
                      and coalesce(credited_minutes, 0) > 0),
      'xp', (select coalesce(sum(amount), 0) from public.xp_transactions
              where user_id = v_user and created_at >= v_week),
      'subjects', (select count(distinct subject_id) from public.study_sessions
                    where user_id = v_user and status = 'completed' and started_at >= v_week
                      and subject_id is not null and coalesce(credited_minutes, 0) > 0)
    ),
    'month', jsonb_build_object(
      'minutes', (select coalesce(sum(credited_minutes), 0) from public.study_sessions
                   where user_id = v_user and status = 'completed' and started_at >= v_month),
      'xp', (select coalesce(sum(amount), 0) from public.xp_transactions
              where user_id = v_user and created_at >= v_month)
    ),
    'totals', jsonb_build_object(
      'minutes', v_p.total_study_seconds / 60,
      'seconds', v_p.total_study_seconds,
      'sessions', v_p.sessions_completed,
      'xp', v_p.xp_total,
      'quests', v_p.quests_completed,
      'achievements', v_p.achievements_count
    ),
    'streak', jsonb_build_object(
      'current', case
                   when v_p.last_study_date is null then 0
                   when v_p.last_study_date >= v_today - 1 then v_p.current_streak
                   else 0
                 end,
      'longest', v_p.longest_streak,
      'last_date', v_p.last_study_date
    ),
    'quests', jsonb_build_object(
      'active', (select count(*) from public.quests
                  where user_id = v_user and status = 'active' and ends_at > now()),
      'completed_today', (select count(*) from public.quests
                           where user_id = v_user and status = 'completed'
                             and completed_at >= v_day),
      'completed_total', (select count(*) from public.quests
                           where user_id = v_user and status = 'completed')
    ),
    'unread_notifications', (select count(*) from public.notifications
                              where user_id = v_user and not is_read),
    'active_session', (
      select to_jsonb(s) from public.study_sessions s
       where s.user_id = v_user and s.status in ('active', 'paused')
       order by s.started_at desc limit 1
    ),
    'config', jsonb_build_object(
      'xp_per_minute', v_cfg.xp_per_minute,
      'daily_xp_cap', v_cfg.daily_xp_cap,
      'min_session_seconds', v_cfg.min_session_seconds,
      'max_session_seconds', v_cfg.max_session_seconds,
      'max_heartbeat_gap', v_cfg.max_heartbeat_gap
    )
  );
end;
$$;

create or replace function public.hunter_daily_series(p_days integer default 30)
returns table (day date, minutes integer, sessions integer, xp integer)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  uuid := auth.uid();
  v_tz    text;
  v_start date;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  select coalesce(nullif(timezone, ''), 'UTC') into v_tz from public.profiles where id = v_user;
  v_tz := coalesce(v_tz, 'UTC');
  v_start := ((now() at time zone v_tz)::date - greatest(least(coalesce(p_days, 30), 365), 1)) + 1;

  return query
  with span as (
    select generate_series(v_start, (now() at time zone v_tz)::date, interval '1 day')::date as d
  ),
  study as (
    select (s.started_at at time zone v_tz)::date as d,
           coalesce(sum(s.credited_minutes), 0)::integer as minutes,
           count(*)::integer as sessions
      from public.study_sessions s
     where s.user_id = v_user
       and s.status = 'completed'
       and coalesce(s.credited_minutes, 0) > 0
       and (s.started_at at time zone v_tz)::date >= v_start
     group by 1
  ),
  xp as (
    select (t.created_at at time zone v_tz)::date as d,
           coalesce(sum(t.amount), 0)::integer as xp
      from public.xp_transactions t
     where t.user_id = v_user
       and (t.created_at at time zone v_tz)::date >= v_start
     group by 1
  )
  select span.d,
         coalesce(study.minutes, 0),
         coalesce(study.sessions, 0),
         coalesce(xp.xp, 0)
    from span
    left join study on study.d = span.d
    left join xp on xp.d = span.d
   order by span.d;
end;
$$;

create or replace function public.hunter_subject_breakdown(p_days integer default 30)
returns table (subject_id uuid, title text, color text, minutes integer, sessions integer)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  uuid := auth.uid();
  v_tz    text;
  v_start timestamptz;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  select coalesce(nullif(timezone, ''), 'UTC') into v_tz from public.profiles where id = v_user;
  v_tz := coalesce(v_tz, 'UTC');
  v_start := ((now() at time zone v_tz)::date - greatest(least(coalesce(p_days, 30), 365), 1) + 1)
               ::timestamp at time zone v_tz;

  return query
  select sub.id as subject_id,
         coalesce(sub.title, 'Unassigned') as title,
         coalesce(sub.color, '#64748b') as color,
         coalesce(sum(s.credited_minutes), 0)::integer as minutes,
         count(*)::integer as sessions
    from public.study_sessions s
    left join public.subjects sub on sub.id = s.subject_id
   where s.user_id = v_user
     and s.status = 'completed'
     and coalesce(s.credited_minutes, 0) > 0
     and s.started_at >= v_start
   group by sub.id
   order by minutes desc;
end;
$$;

create or replace function public.hunter_history(p_limit integer default 20, p_offset integer default 0)
returns table (
  id uuid,
  started_at timestamptz,
  ended_at timestamptz,
  credited_minutes integer,
  xp_awarded integer,
  status public.session_status,
  is_revision boolean,
  note text,
  subject_title text,
  subject_color text,
  topic_title text
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  return query
  select s.id, s.started_at, s.ended_at, s.credited_minutes, s.xp_awarded, s.status,
         s.is_revision, s.note, sub.title, sub.color, t.title
    from public.study_sessions s
    left join public.subjects sub on sub.id = s.subject_id
    left join public.topics t on t.id = s.topic_id
   where s.user_id = v_user
   order by s.started_at desc
   limit greatest(1, least(coalesce(p_limit, 20), 100))
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;

create or replace function public.hunter_history_count()
returns bigint
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select count(*) from public.study_sessions where user_id = auth.uid();
$$;

-- Subject / topic roll-up used by the subjects page.
create or replace function public.subject_summary()
returns table (
  subject_id uuid,
  title text,
  color text,
  archived boolean,
  topics_total integer,
  topics_revised integer,
  minutes_total integer,
  minutes_week integer,
  last_studied_at timestamptz
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select s.id,
         s.title,
         s.color,
         s.archived,
         (select count(*)::integer from public.topics t where t.subject_id = s.id),
         (select count(*)::integer from public.topics t
           where t.subject_id = s.id and t.status in ('revised', 'mastered')),
         coalesce((select sum(x.credited_minutes)::integer from public.study_sessions x
                    where x.subject_id = s.id and x.status = 'completed'), 0),
         coalesce((select sum(x.credited_minutes)::integer from public.study_sessions x
                    where x.subject_id = s.id and x.status = 'completed'
                      and x.started_at >= date_trunc('week', now())), 0),
         (select max(x.started_at) from public.study_sessions x
           where x.subject_id = s.id and x.status = 'completed')
    from public.subjects s
   where s.user_id = auth.uid()
   order by s.archived, s.created_at;
$$;

grant execute on function public.hunter_overview() to authenticated;
grant execute on function public.hunter_daily_series(integer) to authenticated;
grant execute on function public.hunter_subject_breakdown(integer) to authenticated;
grant execute on function public.hunter_history(integer, integer) to authenticated;
grant execute on function public.hunter_history_count() to authenticated;
grant execute on function public.subject_summary() to authenticated;


-- ############################################################################
-- ## 0008_avatar_storage.sql
-- ############################################################################

-- ============================================================================
-- 0008_avatar_storage.sql - Hunter avatars stored in Supabase Storage
-- ----------------------------------------------------------------------------
-- Until now a hunter could only paste a remote image URL into Settings. That
-- meant an arbitrary third-party origin could:
--   * log every visitor who viewed a public profile (tracking pixel),
--   * serve different content per viewer,
--   * disappear and leave a broken profile forever.
--
-- This migration makes avatars first-class project data:
--   1. a public-read `avatars` bucket, 2 MB cap, png/jpeg/webp only;
--   2. storage RLS so a hunter may only write inside `avatars/<own user id>/`;
--   3. a profiles trigger that rejects any avatar_url outside that folder, so
--      the rule holds for every write path (RPC, SQL editor, future code);
--   4. set_my_avatar(), the single RPC the app uses to persist the result.
--
-- The bucket block is skipped on a bare PostgreSQL instance (the local test
-- harness has no `storage` schema); the URL rules still apply there.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. URL rules
-- ----------------------------------------------------------------------------
-- A valid avatar URL is exactly:
--   https://<project>.supabase.<tld>/storage/v1/object/public/avatars/<uid>/<file>
-- where <uid> is the owner. NULL means "no avatar" (generated glyph).
create or replace function public.avatar_url_allowed(p_url text, p_owner uuid)
returns boolean
language sql
immutable
set search_path = ''
as $fn$
  select case
    when p_url is null then true
    when p_owner is null then false
    when char_length(p_url) > 512 then false
    when p_url !~ '^https://[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?/storage/v1/object/public/avatars/[A-Za-z0-9._-]+/[A-Za-z0-9._-]+$'
      then false
    else substring(p_url from '/storage/v1/object/public/avatars/([^/]+)/[^/]+$') = p_owner::text
  end;
$fn$;

comment on function public.avatar_url_allowed(text, uuid) is
  'True when the URL is a public object in the avatars bucket under the owner''s own folder.';

-- ----------------------------------------------------------------------------
-- 2. Bucket + storage policies
-- ----------------------------------------------------------------------------
do $storage$
begin
  if to_regclass('storage.objects') is null or to_regclass('storage.buckets') is null then
    raise notice 'storage schema not found - skipping avatar bucket setup';
    return;
  end if;

  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('avatars', 'avatars', true, 2097152, array['image/png', 'image/jpeg', 'image/webp'])
  on conflict (id) do update
     set public             = excluded.public,
         file_size_limit    = excluded.file_size_limit,
         allowed_mime_types = excluded.allowed_mime_types;

  -- Anyone may read an avatar; it is shown on public profiles and leaderboards.
  execute 'drop policy if exists avatars_read on storage.objects';
  execute $p$create policy avatars_read on storage.objects
              for select to anon, authenticated
              using (bucket_id = 'avatars')$p$;

  -- Writes are restricted to the hunter's own folder: avatars/<auth.uid()>/...
  execute 'drop policy if exists avatars_insert on storage.objects';
  execute $p$create policy avatars_insert on storage.objects
              for insert to authenticated
              with check (
                bucket_id = 'avatars'
                and (storage.foldername(name))[1] = auth.uid()::text
              )$p$;

  execute 'drop policy if exists avatars_update on storage.objects';
  execute $p$create policy avatars_update on storage.objects
              for update to authenticated
              using (
                bucket_id = 'avatars'
                and (storage.foldername(name))[1] = auth.uid()::text
              )
              with check (
                bucket_id = 'avatars'
                and (storage.foldername(name))[1] = auth.uid()::text
              )$p$;

  execute 'drop policy if exists avatars_delete on storage.objects';
  execute $p$create policy avatars_delete on storage.objects
              for delete to authenticated
              using (
                bucket_id = 'avatars'
                and (storage.foldername(name))[1] = auth.uid()::text
              )$p$;
end;
$storage$;

-- ----------------------------------------------------------------------------
-- 3. Enforce the URL rule on every write to profiles
-- ----------------------------------------------------------------------------
create or replace function public.enforce_avatar_url()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $fn$
begin
  if new.avatar_url is not null and btrim(new.avatar_url) = '' then
    new.avatar_url := null;
  end if;

  if not public.avatar_url_allowed(new.avatar_url, new.id) then
    raise exception 'AVATAR_URL_NOT_ALLOWED' using
      errcode = '22023',
      hint    = 'Avatars must be uploaded to the avatars bucket by their owner.';
  end if;

  return new;
end;
$fn$;

-- Clear any pre-existing external URLs before the rule becomes mandatory.
update public.profiles
   set avatar_url = null
 where avatar_url is not null
   and not public.avatar_url_allowed(avatar_url, id);

drop trigger if exists profiles_avatar_url_guard on public.profiles;
create trigger profiles_avatar_url_guard
  before insert or update of avatar_url on public.profiles
  for each row execute function public.enforce_avatar_url();

-- ----------------------------------------------------------------------------
-- 4. The one RPC the app calls after an upload finishes
-- ----------------------------------------------------------------------------
-- Passing NULL clears the avatar and returns the hunter to the generated glyph.
create or replace function public.set_my_avatar(p_avatar_url text default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_user uuid := auth.uid();
  v_url  text := nullif(btrim(coalesce(p_avatar_url, '')), '');
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  if not public.check_rate_limit('set_avatar', 20, 3600) then
    raise exception 'RATE_LIMITED' using errcode = '53400';
  end if;

  if not public.avatar_url_allowed(v_url, v_user) then
    raise exception 'INVALID_AVATAR_URL' using errcode = '22023';
  end if;

  update public.profiles
     set avatar_url = v_url
   where id = v_user;

  return jsonb_build_object('avatar_url', v_url);
end;
$fn$;

revoke all on function public.avatar_url_allowed(text, uuid) from public;
revoke all on function public.set_my_avatar(text) from public;

grant execute on function public.avatar_url_allowed(text, uuid) to anon, authenticated;
grant execute on function public.set_my_avatar(text) to authenticated;


-- ############################################################################
-- ## 0009_social_friends.sql
-- ############################################################################

-- ============================================================================
-- 0009_social_friends.sql - Hunter friends + friends leaderboard
-- ----------------------------------------------------------------------------
-- A friendship is a single row for a pair of hunters, owned jointly by the
-- requester and the addressee. Clients can read rows they are part of and can
-- write nothing: every transition (request, accept, decline, unfriend) goes
-- through a SECURITY DEFINER function that re-checks auth.uid() and the current
-- state of the row.
--
-- Nothing here can be used to read another hunter's private data: the exposed
-- columns are the same public ones the leaderboard already shows.
-- ============================================================================

create table public.friendships (
  requester_id uuid not null references public.profiles (id) on delete cascade,
  addressee_id uuid not null references public.profiles (id) on delete cascade,
  status       text not null default 'pending'
                 check (status in ('pending', 'accepted', 'declined')),
  created_at   timestamptz not null default now(),
  responded_at timestamptz,
  primary key (requester_id, addressee_id),
  constraint friendships_no_self check (requester_id <> addressee_id)
);

create index friendships_requester_idx on public.friendships (requester_id, status);
create index friendships_addressee_idx on public.friendships (addressee_id, status);

alter table public.friendships enable row level security;

revoke all on public.friendships from anon, authenticated;
grant select on public.friendships to authenticated;

create policy friendships_read_own on public.friendships
  for select to authenticated
  using (requester_id = auth.uid() or addressee_id = auth.uid());

-- ----------------------------------------------------------------------------
-- Helpers
-- ----------------------------------------------------------------------------
create or replace function public.are_friends(p_a uuid, p_b uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.friendships f
     where f.status = 'accepted'
       and ((f.requester_id = p_a and f.addressee_id = p_b)
         or (f.requester_id = p_b and f.addressee_id = p_a))
  );
$$;

/** Resolve a handle to a reachable hunter id, or raise. */
create or replace function public.hunter_id_by_username(p_username text)
returns uuid
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  select id into v_id
    from public.profiles
   where lower(username) = lower(btrim(coalesce(p_username, '')))
     and is_public
   limit 1;

  if v_id is null then
    raise exception 'HUNTER_NOT_FOUND' using errcode = 'P0002';
  end if;
  return v_id;
end;
$$;

-- ----------------------------------------------------------------------------
-- Transitions
-- ----------------------------------------------------------------------------
create or replace function public.send_friend_request(p_username text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user    uuid := auth.uid();
  v_target  uuid;
  v_existing public.friendships;
  v_status  text;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;
  if not public.check_rate_limit('friend_request', 30, 3600) then
    raise exception 'RATE_LIMITED' using errcode = '53400';
  end if;

  v_target := public.hunter_id_by_username(p_username);

  if v_target = v_user then
    raise exception 'CANNOT_FRIEND_SELF' using errcode = '22023';
  end if;

  select * into v_existing from public.friendships
   where (requester_id = v_user and addressee_id = v_target)
      or (requester_id = v_target and addressee_id = v_user)
   limit 1;

  if v_existing.requester_id is not null then
    if v_existing.status = 'accepted' then
      raise exception 'ALREADY_FRIENDS' using errcode = '23505';
    end if;

    if v_existing.status = 'pending' then
      -- They already asked us: treat this as an acceptance.
      if v_existing.requester_id = v_target then
        update public.friendships
           set status = 'accepted', responded_at = now()
         where requester_id = v_target and addressee_id = v_user;
        v_status := 'accepted';
      else
        raise exception 'REQUEST_ALREADY_SENT' using errcode = '23505';
      end if;
    else
      -- A previous decline: reopen the record with the new direction.
      delete from public.friendships
       where requester_id = v_existing.requester_id
         and addressee_id = v_existing.addressee_id;
      insert into public.friendships (requester_id, addressee_id)
      values (v_user, v_target);
      v_status := 'pending';
    end if;
  else
    insert into public.friendships (requester_id, addressee_id)
    values (v_user, v_target);
    v_status := 'pending';
  end if;

  insert into public.notifications (user_id, type, title, message, payload)
  values (
    case when v_status = 'accepted' then v_user else v_target end,
    'system',
    case when v_status = 'accepted' then 'Friend added' else 'Friend request' end,
    case when v_status = 'accepted'
         then 'A hunter accepted your friend request.'
         else 'A hunter wants to join your roster.' end,
    jsonb_build_object('kind', 'friendship', 'status', v_status, 'hunter_id', v_user)
  );

  return jsonb_build_object('status', v_status, 'username', p_username);
end;
$$;

create or replace function public.respond_friend_request(p_requester uuid, p_accept boolean)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  update public.friendships
     set status = case when coalesce(p_accept, false) then 'accepted' else 'declined' end,
         responded_at = now()
   where requester_id = p_requester
     and addressee_id = v_user
     and status = 'pending';

  if not found then
    raise exception 'REQUEST_NOT_FOUND' using errcode = 'P0002';
  end if;

  if coalesce(p_accept, false) then
    insert into public.notifications (user_id, type, title, message, payload)
    values (p_requester, 'system', 'Friend added', 'A hunter accepted your friend request.',
            jsonb_build_object('kind', 'friendship', 'status', 'accepted', 'hunter_id', v_user));
  end if;

  return jsonb_build_object('accepted', coalesce(p_accept, false));
end;
$$;

-- Removes a friendship, or withdraws a request this hunter sent.
create or replace function public.remove_friend(p_other uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_count integer;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  delete from public.friendships
   where (requester_id = v_user and addressee_id = p_other)
      or (requester_id = p_other and addressee_id = v_user);
  get diagnostics v_count = row_count;

  return jsonb_build_object('removed', v_count);
end;
$$;

-- ----------------------------------------------------------------------------
-- Reads
-- ----------------------------------------------------------------------------
create or replace function public.list_friends()
returns table (
  user_id          uuid,
  username         text,
  display_name     text,
  avatar_url       text,
  hunter_rank      text,
  level            integer,
  xp_total         bigint,
  current_streak   integer,
  sessions_completed integer,
  friends_since    timestamptz
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select p.id,
         p.username,
         coalesce(p.display_name, p.username),
         p.avatar_url,
         p.rank::text,
         p.level,
         p.xp_total,
         p.current_streak,
         p.sessions_completed,
         coalesce(f.responded_at, f.created_at)
    from public.friendships f
    join public.profiles p
      on p.id = case when f.requester_id = auth.uid() then f.addressee_id else f.requester_id end
   where f.status = 'accepted'
     and (f.requester_id = auth.uid() or f.addressee_id = auth.uid())
   order by p.xp_total desc, p.username asc;
$$;

create or replace function public.list_friend_requests()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'incoming', coalesce((
      select jsonb_agg(jsonb_build_object(
               'user_id', p.id, 'username', p.username,
               'display_name', coalesce(p.display_name, p.username),
               'avatar_url', p.avatar_url, 'hunter_rank', p.rank::text,
               'level', p.level, 'xp_total', p.xp_total,
               'requested_at', f.created_at
             ) order by f.created_at desc)
        from public.friendships f
        join public.profiles p on p.id = f.requester_id
       where f.addressee_id = auth.uid() and f.status = 'pending'
    ), '[]'::jsonb),
    'outgoing', coalesce((
      select jsonb_agg(jsonb_build_object(
               'user_id', p.id, 'username', p.username,
               'display_name', coalesce(p.display_name, p.username),
               'avatar_url', p.avatar_url, 'hunter_rank', p.rank::text,
               'level', p.level, 'xp_total', p.xp_total,
               'requested_at', f.created_at
             ) order by f.created_at desc)
        from public.friendships f
        join public.profiles p on p.id = f.addressee_id
       where f.requester_id = auth.uid() and f.status = 'pending'
    ), '[]'::jsonb)
  );
$$;

-- Public hunter search with the relationship to the caller, so the roster page
-- can render the right button without a second round trip.
create or replace function public.search_hunters(p_query text, p_limit integer default 10)
returns table (
  user_id      uuid,
  username     text,
  display_name text,
  avatar_url   text,
  hunter_rank  text,
  level        integer,
  xp_total     bigint,
  relationship text
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with q as (
    select btrim(coalesce(p_query, '')) as term
  )
  select p.id,
         p.username,
         coalesce(p.display_name, p.username),
         p.avatar_url,
         p.rank::text,
         p.level,
         p.xp_total,
         case
           when p.id = auth.uid() then 'self'
           when exists (
             select 1 from public.friendships f
              where f.status = 'accepted'
                and ((f.requester_id = auth.uid() and f.addressee_id = p.id)
                  or (f.requester_id = p.id and f.addressee_id = auth.uid()))
           ) then 'friend'
           when exists (
             select 1 from public.friendships f
              where f.status = 'pending' and f.requester_id = auth.uid() and f.addressee_id = p.id
           ) then 'outgoing'
           when exists (
             select 1 from public.friendships f
              where f.status = 'pending' and f.requester_id = p.id and f.addressee_id = auth.uid()
           ) then 'incoming'
           else 'none'
         end as relationship
    from public.profiles p, q
   where p.is_public
     and char_length(q.term) >= 2
     and p.username ilike '%' || q.term || '%'
   order by (p.username ilike q.term || '%') desc, p.xp_total desc
   limit greatest(1, least(coalesce(p_limit, 10), 25));
$$;

-- Friends board: the caller plus accepted friends, including hunters who opted
-- out of the global board. Private hunters stay excluded.
create or replace function public.friend_leaderboard(
  p_period text default 'all',
  p_limit  integer default 50
)
returns table (
  rank_position bigint,
  user_id       uuid,
  username      text,
  display_name  text,
  avatar_url    text,
  hunter_rank   text,
  level         integer,
  period_xp     bigint,
  is_me         boolean
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with v as (
    select public.leaderboard_period_start(p_period) as period_start
  ),
  circle as (
    select auth.uid() as id
    union
    select case when f.requester_id = auth.uid() then f.addressee_id else f.requester_id end
      from public.friendships f
     where f.status = 'accepted'
       and (f.requester_id = auth.uid() or f.addressee_id = auth.uid())
  ),
  scored as (
    select p.id, p.username,
           coalesce(p.display_name, p.username) as display_name,
           p.avatar_url, p.rank::text as hunter_rank, p.level, p.created_at, p.xp_total,
           case
             when v.period_start is null then p.xp_total
             else coalesce((
               select sum(t.amount)::bigint from public.xp_transactions t
                where t.user_id = p.id and t.created_at >= v.period_start
             ), 0)
           end as period_xp
      from public.profiles p
      join circle c on c.id = p.id
      cross join v
     where p.is_public
  ),
  ranked as (
    select s.*, row_number() over (
      order by s.period_xp desc, s.xp_total desc, s.created_at asc, s.id asc
    ) as pos
      from scored s
  )
  select r.pos, r.id, r.username, r.display_name, r.avatar_url,
         r.hunter_rank, r.level, r.period_xp, r.id = auth.uid()
    from ranked r
   order by r.pos
   limit greatest(1, least(coalesce(p_limit, 50), 100));
$$;

revoke all on function public.are_friends(uuid, uuid) from public;
revoke all on function public.hunter_id_by_username(text) from public;

grant execute on function public.are_friends(uuid, uuid) to authenticated;
grant execute on function public.hunter_id_by_username(text) to authenticated;
grant execute on function public.send_friend_request(text) to authenticated;
grant execute on function public.respond_friend_request(uuid, boolean) to authenticated;
grant execute on function public.remove_friend(uuid) to authenticated;
grant execute on function public.list_friends() to authenticated;
grant execute on function public.list_friend_requests() to authenticated;
grant execute on function public.search_hunters(text, integer) to authenticated;
grant execute on function public.friend_leaderboard(text, integer) to authenticated;


-- ############################################################################
-- ## 0010_guilds.sql
-- ############################################################################

-- ============================================================================
-- 0010_guilds.sql - Hunter guilds, rosters and the guild board
-- ----------------------------------------------------------------------------
-- A guild is a small persistent party of hunters. Membership is one-per-hunter
-- (enforced by a unique index, not by hope), and every write goes through a
-- SECURITY DEFINER function so a client can never add itself to a guild, edit
-- someone else's roster, or inflate a score.
--
-- Guild score = the sum of the period XP of its members, computed from the same
-- xp_transactions ledger the hunter leaderboard uses. Nobody can award guild XP
-- directly.
-- ============================================================================

create table public.guilds (
  id            uuid primary key default gen_random_uuid(),
  name          text not null check (char_length(btrim(name)) between 3 and 32),
  slug          text not null unique check (slug ~ '^[a-z0-9-]{3,48}$'),
  tag           text not null check (tag ~ '^[A-Z0-9]{2,5}$'),
  description   text check (description is null or char_length(description) <= 280),
  emblem_color  text not null default '#38e1ff' check (emblem_color ~ '^#[0-9A-Fa-f]{6}$'),
  owner_id      uuid not null references public.profiles (id) on delete cascade,
  is_open       boolean not null default true,
  member_limit  integer not null default 30 check (member_limit between 2 and 100),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create unique index guilds_name_lower_idx on public.guilds (lower(btrim(name)));

create table public.guild_members (
  guild_id  uuid not null references public.guilds (id) on delete cascade,
  user_id   uuid not null references public.profiles (id) on delete cascade,
  role      text not null default 'member' check (role in ('leader', 'officer', 'member')),
  joined_at timestamptz not null default now(),
  primary key (guild_id, user_id)
);

-- One guild per hunter.
create unique index guild_members_one_guild_idx on public.guild_members (user_id);
create index guild_members_guild_idx on public.guild_members (guild_id, joined_at);

create trigger guilds_touch before update on public.guilds
  for each row execute function public.tg_touch_updated_at();

alter table public.guilds enable row level security;
alter table public.guild_members enable row level security;

revoke all on public.guilds from anon, authenticated;
revoke all on public.guild_members from anon, authenticated;
grant select on public.guilds to anon, authenticated;
grant select on public.guild_members to authenticated;

create policy guilds_read_all on public.guilds
  for select to anon, authenticated using (true);

create policy guild_members_read_all on public.guild_members
  for select to authenticated using (true);

-- ----------------------------------------------------------------------------
-- Helpers
-- ----------------------------------------------------------------------------
create or replace function public.guild_of(p_user uuid)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select gm.guild_id from public.guild_members gm where gm.user_id = p_user;
$$;

create or replace function public.guild_role_of(p_user uuid, p_guild uuid)
returns text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select gm.role from public.guild_members gm
   where gm.user_id = p_user and gm.guild_id = p_guild;
$$;

create or replace function public.guild_slug(p_name text, p_tag text)
returns text
language plpgsql
volatile
as $$
declare
  base text;
  candidate text;
  n integer := 1;
begin
  base := lower(btrim(p_name));
  base := regexp_replace(base, '[^a-z0-9]+', '-', 'g');
  base := btrim(base, '-');
  if char_length(base) < 3 then
    base := lower(p_tag) || '-' || base;
  end if;
  base := left(base, 40);
  candidate := base;

  while exists (select 1 from public.guilds g where g.slug = candidate) loop
    n := n + 1;
    candidate := left(base, 40) || '-' || n::text;
  end loop;

  return candidate;
end;
$$;

-- ----------------------------------------------------------------------------
-- Create / join / leave
-- ----------------------------------------------------------------------------
create or replace function public.create_guild(
  p_name        text,
  p_tag         text,
  p_description text default null,
  p_is_open     boolean default true,
  p_color       text default '#38e1ff'
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_name text := btrim(coalesce(p_name, ''));
  v_tag  text := upper(btrim(coalesce(p_tag, '')));
  v_id   uuid;
  v_slug text;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;
  if not public.check_rate_limit('create_guild', 5, 86400) then
    raise exception 'RATE_LIMITED' using errcode = '53400';
  end if;
  if char_length(v_name) < 3 or char_length(v_name) > 32 then
    raise exception 'INVALID_GUILD_NAME' using errcode = '22023';
  end if;
  if v_tag !~ '^[A-Z0-9]{2,5}$' then
    raise exception 'INVALID_GUILD_TAG' using errcode = '22023';
  end if;
  if p_color !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception 'INVALID_GUILD_COLOR' using errcode = '22023';
  end if;
  if public.guild_of(v_user) is not null then
    raise exception 'ALREADY_IN_GUILD' using errcode = '23505';
  end if;
  if exists (select 1 from public.guilds g where lower(btrim(g.name)) = lower(v_name)) then
    raise exception 'GUILD_NAME_TAKEN' using errcode = '23505';
  end if;

  v_slug := public.guild_slug(v_name, v_tag);

  insert into public.guilds (name, slug, tag, description, emblem_color, owner_id, is_open)
  values (v_name, v_slug, v_tag, nullif(btrim(coalesce(p_description, '')), ''), p_color, v_user,
          coalesce(p_is_open, true))
  returning id into v_id;

  insert into public.guild_members (guild_id, user_id, role) values (v_id, v_user, 'leader');

  insert into public.notifications (user_id, type, title, message, payload)
  values (v_user, 'system', 'Guild founded', 'Your guild is registered with the Association.',
          jsonb_build_object('kind', 'guild', 'guild_id', v_id));

  return jsonb_build_object('guild_id', v_id, 'slug', v_slug);
end;
$$;

create or replace function public.join_guild(p_guild_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  uuid := auth.uid();
  v_guild public.guilds;
  v_count integer;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;
  if not public.check_rate_limit('join_guild', 20, 3600) then
    raise exception 'RATE_LIMITED' using errcode = '53400';
  end if;

  select * into v_guild from public.guilds where id = p_guild_id;
  if v_guild.id is null then
    raise exception 'GUILD_NOT_FOUND' using errcode = 'P0002';
  end if;
  if public.guild_of(v_user) is not null then
    raise exception 'ALREADY_IN_GUILD' using errcode = '23505';
  end if;
  if not v_guild.is_open then
    raise exception 'GUILD_CLOSED' using errcode = '22023';
  end if;

  select count(*) into v_count from public.guild_members where guild_id = v_guild.id;
  if v_count >= v_guild.member_limit then
    raise exception 'GUILD_FULL' using errcode = '22023';
  end if;

  insert into public.guild_members (guild_id, user_id) values (v_guild.id, v_user);

  insert into public.notifications (user_id, type, title, message, payload)
  values (v_guild.owner_id, 'system', 'New guild member', 'A hunter joined your guild.',
          jsonb_build_object('kind', 'guild', 'guild_id', v_guild.id, 'hunter_id', v_user));

  return jsonb_build_object('guild_id', v_guild.id, 'slug', v_guild.slug);
end;
$$;

-- The leader hands over to the longest-serving officer (or member) when they
-- leave; the last member out dissolves the guild.
create or replace function public.leave_guild()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  uuid := auth.uid();
  v_guild uuid;
  v_role  text;
  v_next  uuid;
  v_left  integer;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  v_guild := public.guild_of(v_user);
  if v_guild is null then
    raise exception 'NOT_IN_GUILD' using errcode = 'P0002';
  end if;
  v_role := public.guild_role_of(v_user, v_guild);

  delete from public.guild_members where guild_id = v_guild and user_id = v_user;

  select count(*) into v_left from public.guild_members where guild_id = v_guild;

  if v_left = 0 then
    delete from public.guilds where id = v_guild;
    return jsonb_build_object('left', true, 'dissolved', true);
  end if;

  if v_role = 'leader' then
    select user_id into v_next
      from public.guild_members
     where guild_id = v_guild
     order by (role = 'officer') desc, joined_at asc
     limit 1;

    update public.guild_members set role = 'leader'
     where guild_id = v_guild and user_id = v_next;
    update public.guilds set owner_id = v_next where id = v_guild;

    insert into public.notifications (user_id, type, title, message, payload)
    values (v_next, 'system', 'Guild leadership', 'You are now the leader of your guild.',
            jsonb_build_object('kind', 'guild', 'guild_id', v_guild));
  end if;

  return jsonb_build_object('left', true, 'dissolved', false);
end;
$$;

-- Leader-only settings; officers may promote and remove members.
create or replace function public.update_my_guild(
  p_description text default null,
  p_is_open     boolean default null,
  p_color       text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  uuid := auth.uid();
  v_guild uuid := public.guild_of(auth.uid());
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;
  if v_guild is null then
    raise exception 'NOT_IN_GUILD' using errcode = 'P0002';
  end if;
  if public.guild_role_of(v_user, v_guild) <> 'leader' then
    raise exception 'GUILD_LEADER_ONLY' using errcode = '42501';
  end if;
  if p_color is not null and p_color !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception 'INVALID_GUILD_COLOR' using errcode = '22023';
  end if;

  update public.guilds
     set description = case when p_description is null then description
                            else nullif(btrim(p_description), '') end,
         is_open = coalesce(p_is_open, is_open),
         emblem_color = coalesce(p_color, emblem_color)
   where id = v_guild;

  return (select to_jsonb(g) from public.guilds g where g.id = v_guild);
end;
$$;

create or replace function public.remove_guild_member(p_user uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user   uuid := auth.uid();
  v_guild  uuid := public.guild_of(auth.uid());
  v_actor  text;
  v_target text;
  v_count  integer;
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;
  if v_guild is null then
    raise exception 'NOT_IN_GUILD' using errcode = 'P0002';
  end if;

  v_actor := public.guild_role_of(v_user, v_guild);
  v_target := public.guild_role_of(p_user, v_guild);

  if p_user is null or v_target is null then
    raise exception 'NOT_IN_GUILD' using errcode = 'P0002';
  end if;
  if p_user = v_user then
    raise exception 'USE_LEAVE_GUILD' using errcode = '22023';
  end if;
  if v_target = 'leader' then
    raise exception 'CANNOT_REMOVE_LEADER' using errcode = '42501';
  end if;
  if v_actor not in ('leader', 'officer') then
    raise exception 'GUILD_LEADER_ONLY' using errcode = '42501';
  end if;
  if v_actor = 'officer' and v_target = 'officer' then
    raise exception 'GUILD_LEADER_ONLY' using errcode = '42501';
  end if;

  delete from public.guild_members where guild_id = v_guild and user_id = p_user;
  get diagnostics v_count = row_count;

  return jsonb_build_object('removed', v_count);
end;
$$;

create or replace function public.set_guild_member_role(p_user uuid, p_role text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  uuid := auth.uid();
  v_guild uuid := public.guild_of(auth.uid());
begin
  if v_user is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;
  if v_guild is null or public.guild_role_of(v_user, v_guild) <> 'leader' then
    raise exception 'GUILD_LEADER_ONLY' using errcode = '42501';
  end if;
  if p_role not in ('officer', 'member') then
    raise exception 'INVALID_GUILD_ROLE' using errcode = '22023';
  end if;
  if p_user = v_user then
    raise exception 'CANNOT_DEMOTE_LEADER' using errcode = '22023';
  end if;

  update public.guild_members set role = p_role
   where guild_id = v_guild and user_id = p_user;

  return jsonb_build_object('role', p_role);
end;
$$;

-- ----------------------------------------------------------------------------
-- Reads
-- ----------------------------------------------------------------------------
create or replace function public.guild_leaderboard(
  p_period text default 'week',
  p_limit  integer default 20,
  p_search text default null
)
returns table (
  rank_position bigint,
  guild_id      uuid,
  name          text,
  slug          text,
  tag           text,
  emblem_color  text,
  member_count  integer,
  period_xp     bigint,
  is_my_guild   boolean
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with v as (
    select public.leaderboard_period_start(p_period) as period_start
  ),
  scored as (
    select g.id, g.name, g.slug, g.tag, g.emblem_color,
           coalesce(count(gm.user_id), 0)::int as member_count,
           coalesce((
             select sum(case
                          when v.period_start is null then p.xp_total
                          else coalesce((
                            select sum(t.amount)::bigint from public.xp_transactions t
                             where t.user_id = gm2.user_id and t.created_at >= v.period_start
                          ), 0)
                        end)
               from public.guild_members gm2
               join public.profiles p on p.id = gm2.user_id
              where gm2.guild_id = g.id
           ), 0)::bigint as period_xp
      from public.guilds g
      left join public.guild_members gm on gm.guild_id = g.id
      cross join v
     where p_search is null or btrim(p_search) = ''
        or g.name ilike '%' || btrim(p_search) || '%'
        or g.tag ilike '%' || btrim(p_search) || '%'
     group by g.id, g.name, g.slug, g.tag, g.emblem_color, v.period_start
  ),
  ranked as (
    select s.*, row_number() over (
      order by s.period_xp desc, s.member_count desc, s.name asc
    ) as pos
      from scored s
  )
  select r.pos, r.id, r.name, r.slug, r.tag, r.emblem_color,
         r.member_count, r.period_xp,
         exists (select 1 from public.guild_members m
                  where m.guild_id = r.id and m.user_id = auth.uid())
    from ranked r
   order by r.pos
   limit greatest(1, least(coalesce(p_limit, 20), 50));
$$;

create or replace function public.guild_roster(p_guild_id uuid)
returns table (
  user_id      uuid,
  username     text,
  display_name text,
  avatar_url   text,
  hunter_rank  text,
  level        integer,
  xp_total     bigint,
  guild_role   text,
  joined_at    timestamptz,
  is_me        boolean
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select p.id, p.username, coalesce(p.display_name, p.username), p.avatar_url,
         p.rank::text, p.level, p.xp_total, gm.role, gm.joined_at, p.id = auth.uid()
    from public.guild_members gm
    join public.profiles p on p.id = gm.user_id
   where gm.guild_id = p_guild_id
     and p.is_public
   order by (gm.role = 'leader') desc, (gm.role = 'officer') desc, gm.joined_at asc;
$$;

-- Everything the guild page needs in one payload.
create or replace function public.guild_detail(p_slug text)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with g as (
    select * from public.guilds where slug = lower(btrim(coalesce(p_slug, ''))) limit 1
  ),
  agg as (
    select coalesce(count(*), 0)::int as member_count,
           coalesce(sum(p.xp_total), 0)::bigint as xp_total,
           coalesce(sum(p.total_study_seconds), 0)::bigint as study_seconds,
           coalesce(sum(p.sessions_completed), 0)::int as sessions
      from public.guild_members gm
      join public.profiles p on p.id = gm.user_id
      join g on g.id = gm.guild_id
  ),
  week as (
    select coalesce(sum(t.amount), 0)::bigint as xp
      from public.guild_members gm
      join public.xp_transactions t on t.user_id = gm.user_id
      join g on g.id = gm.guild_id
     where t.created_at >= date_trunc('week', now())
  ),
  members as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'user_id', p.id, 'username', p.username,
             'display_name', coalesce(p.display_name, p.username),
             'avatar_url', p.avatar_url, 'rank', p.rank::text,
             'level', p.level, 'xp_total', p.xp_total,
             'role', gm.role, 'joined_at', gm.joined_at
           ) order by (gm.role = 'leader') desc, (gm.role = 'officer') desc, gm.joined_at asc), '[]'::jsonb) as items
      from public.guild_members gm
      join public.profiles p on p.id = gm.user_id
      join g on g.id = gm.guild_id
  ),
  standing as (
    select r.rank_position from public.guild_leaderboard('week', 50, null) r, g where r.guild_id = g.id
  )
  select case when g.id is null then null else jsonb_build_object(
    'id', g.id, 'name', g.name, 'slug', g.slug, 'tag', g.tag,
    'description', g.description, 'emblem_color', g.emblem_color,
    'owner_id', g.owner_id, 'is_open', g.is_open, 'member_limit', g.member_limit,
    'created_at', g.created_at,
    'member_count', (select member_count from agg),
    'xp_total', (select xp_total from agg),
    'study_seconds', (select study_seconds from agg),
    'sessions', (select sessions from agg),
    'weekly_xp', (select xp from week),
    'weekly_position', (select rank_position from standing),
    'members', (select items from members),
    'my_role', public.guild_role_of(auth.uid(), g.id)
  ) end
  from g;
$$;

create or replace function public.my_guild()
returns text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select g.slug
    from public.guild_members gm
    join public.guilds g on g.id = gm.guild_id
   where gm.user_id = auth.uid();
$$;

revoke all on function public.guild_of(uuid) from public;
revoke all on function public.guild_role_of(uuid, uuid) from public;
revoke all on function public.guild_slug(text, text) from public;

grant execute on function public.guild_of(uuid) to authenticated;
grant execute on function public.guild_role_of(uuid, uuid) to authenticated;
grant execute on function public.create_guild(text, text, text, boolean, text) to authenticated;
grant execute on function public.join_guild(uuid) to authenticated;
grant execute on function public.leave_guild() to authenticated;
grant execute on function public.update_my_guild(text, boolean, text) to authenticated;
grant execute on function public.remove_guild_member(uuid) to authenticated;
grant execute on function public.set_guild_member_role(uuid, text) to authenticated;
grant execute on function public.guild_leaderboard(text, integer, text) to anon, authenticated;
grant execute on function public.guild_roster(uuid) to anon, authenticated;
grant execute on function public.guild_detail(text) to anon, authenticated;
grant execute on function public.my_guild() to authenticated;


-- ############################################################################
-- ## 0011_seasons.sql
-- ############################################################################

-- ============================================================================
-- 0011_seasons.sql - Monthly hunter seasons
-- ----------------------------------------------------------------------------
-- A season is one calendar month. The catalog is generated deterministically
-- from the database clock (twelve months back, one forward) so no scheduler and
-- no manual seeding is required, and every row carries a name and a theme the
-- owner can edit later with a plain UPDATE.
--
-- Season standings are derived from the same xp_transactions ledger as every
-- other board. Nothing can write season XP directly.
-- ============================================================================

create table public.seasons (
  code      text primary key check (code ~ '^[0-9]{4}-[0-9]{2}$'),
  name      text not null,
  theme     text not null default 'azure' check (theme in ('azure', 'violet', 'gold', 'ember')),
  starts_at timestamptz not null,
  ends_at   timestamptz not null,
  created_at timestamptz not null default now(),
  constraint seasons_window_valid check (ends_at > starts_at)
);

create index seasons_window_idx on public.seasons (starts_at, ends_at);

alter table public.seasons enable row level security;
revoke all on public.seasons from anon, authenticated;
grant select on public.seasons to anon, authenticated;

create policy seasons_public on public.seasons
  for select to anon, authenticated using (true);

insert into public.seasons (code, name, theme, starts_at, ends_at)
select to_char(m, 'YYYY-MM'),
       'Season ' || to_char(m, 'YYYY-MM'),
       (array['azure', 'violet', 'gold', 'ember'])[1 + (extract(month from m)::int % 4)],
       m,
       m + interval '1 month'
  from generate_series(
         date_trunc('month', now()) - interval '11 months',
         date_trunc('month', now()) + interval '1 month',
         interval '1 month'
       ) as m
on conflict (code) do nothing;

-- ----------------------------------------------------------------------------
-- Current season
-- ----------------------------------------------------------------------------
create or replace function public.current_season()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'code', s.code,
    'name', s.name,
    'theme', s.theme,
    'starts_at', s.starts_at,
    'ends_at', s.ends_at,
    'days_left', greatest(0, ceil(extract(epoch from (s.ends_at - now())) / 86400))::int
  )
    from public.seasons s
   where now() >= s.starts_at and now() < s.ends_at
   order by s.starts_at desc
   limit 1;
$$;

-- ----------------------------------------------------------------------------
-- Season standings
-- ----------------------------------------------------------------------------
create or replace function public.season_leaderboard(
  p_code  text default null,
  p_limit integer default 25
)
returns table (
  rank_position bigint,
  user_id       uuid,
  username      text,
  display_name  text,
  avatar_url    text,
  hunter_rank   text,
  level         integer,
  period_xp     bigint,
  is_me         boolean
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with target as (
    select s.*
      from public.seasons s
     where (p_code is null and now() >= s.starts_at and now() < s.ends_at)
        or (p_code is not null and s.code = btrim(p_code))
     order by s.starts_at desc
     limit 1
  ),
  scored as (
    select p.id, p.username,
           coalesce(p.display_name, p.username) as display_name,
           p.avatar_url, p.rank::text as hunter_rank, p.level, p.created_at, p.xp_total,
           coalesce((
             select sum(t.amount)::bigint
               from public.xp_transactions t, target tg
              where t.user_id = p.id
                and t.created_at >= tg.starts_at
                and t.created_at < tg.ends_at
           ), 0) as period_xp
      from public.profiles p
      cross join target
     where p.is_public and p.show_on_leaderboard
  ),
  ranked as (
    select s.*, row_number() over (
      order by s.period_xp desc, s.xp_total desc, s.created_at asc, s.id asc
    ) as pos
      from scored s
     where s.period_xp > 0
  )
  select r.pos, r.id, r.username, r.display_name, r.avatar_url,
         r.hunter_rank, r.level, r.period_xp, r.id = auth.uid()
    from ranked r
   order by r.pos
   limit greatest(1, least(coalesce(p_limit, 25), 100));
$$;

-- Top three of the season that just ended, for the "last season" highlight.
create or replace function public.previous_season_summary()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with prev as (
    select s.* from public.seasons s
     where s.ends_at <= now()
     order by s.starts_at desc
     limit 1
  ),
  winners as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'rank_position', w.rank_position,
             'username', w.username,
             'display_name', w.display_name,
             'avatar_url', w.avatar_url,
             'hunter_rank', w.hunter_rank,
             'level', w.level,
             'period_xp', w.period_xp
           ) order by w.rank_position), '[]'::jsonb) as items
      from public.season_leaderboard((select code from prev), 3) w
  )
  select case when (select code from prev) is null then null else jsonb_build_object(
    'code', (select code from prev),
    'name', (select name from prev),
    'theme', (select theme from prev),
    'ends_at', (select ends_at from prev),
    'winners', (select items from winners)
  ) end;
$$;

-- The caller's own season record: XP this season, position, and the gap to the
-- hunter immediately above them.
create or replace function public.my_season_standing()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with me as (
    select id, xp_total, is_public, show_on_leaderboard from public.profiles where id = auth.uid()
  ),
  board as (
    select * from public.season_leaderboard(null, 100)
  ),
  mine as (
    select b.* from board b, me where b.user_id = me.id
  ),
  above as (
    select b.period_xp
      from board b, mine m
     where b.rank_position = m.rank_position - 1
  )
  select jsonb_build_object(
    'listed', (select me.is_public and me.show_on_leaderboard from me),
    'season_xp', coalesce((select period_xp from mine), 0),
    'position', (select rank_position from mine),
    'total', (select count(*) from board),
    'gap_to_above', coalesce((select period_xp from above), 0) - coalesce((select period_xp from mine), 0)
  );
$$;

grant execute on function public.current_season() to anon, authenticated;
grant execute on function public.season_leaderboard(text, integer) to anon, authenticated;
grant execute on function public.previous_season_summary() to anon, authenticated;
grant execute on function public.my_season_standing() to authenticated;

-- ----------------------------------------------------------------------------
-- Hardening: Postgres grants EXECUTE on every new function to PUBLIC, so the
-- implicit grant is stripped again here for each SECURITY DEFINER function.
-- Explicit grants made in this and earlier migrations are unaffected.
-- ----------------------------------------------------------------------------
do $harden$
declare
  fn text;
begin
  for fn in
    select p.oid::regprocedure::text
      from pg_proc p
     where p.pronamespace = 'public'::regnamespace
       and p.prosecdef
  loop
    execute format('revoke all on function %s from public', fn);
  end loop;
end;
$harden$;


-- ############################################################################
-- ## 0012_public_profile_columns.sql
-- ############################################################################

-- ============================================================================
-- 0012_public_profile_columns.sql - trim what anonymous visitors can read
-- ----------------------------------------------------------------------------
-- Before this migration `grant select on public.profiles to anon` exposed every
-- column of a public profile: timezone, daily goal, last study date, role.
-- RLS limited the *rows* but not the *fields*, so an anonymous scrape of
-- /leaderboard data could recover behavioural details that the leaderboard RPC
-- deliberately omits.
--
-- Anonymous readers now get only the fields a public hunter card is made of.
-- Authenticated users keep the table grant because they read their own row
-- (RLS) and the app selects explicit columns everywhere.
-- ============================================================================

revoke select on public.profiles from anon;

grant select (
  id,
  hunter_id,
  username,
  display_name,
  avatar_url,
  bio,
  level,
  rank,
  xp_total,
  total_study_seconds,
  sessions_completed,
  quests_completed,
  achievements_count,
  current_streak,
  longest_streak,
  awakened_at,
  created_at,
  is_public
) on public.profiles to anon;

comment on table public.profiles is
  'Hunter identity and lifetime totals. Server-managed: xp_total, level, rank, '
  'streaks and counters are only written by SECURITY DEFINER RPCs. Anonymous '
  'readers are limited to the public hunter-card columns (see 0012).';


-- ############################################################################
-- ## 0013_admin_console.sql
-- ############################################################################

-- ============================================================================
-- 0013_admin_console.sql - moderation surface for staff
-- ----------------------------------------------------------------------------
-- The `hunter_role` column has existed since 0001 but nothing read it. This
-- adds the read-only moderation views plus a narrow role-management RPC.
--
-- Rules enforced in the database, not the UI:
--   * only 'staff' (moderator or admin) may read the console RPCs;
--   * only an admin may change a role;
--   * nobody may change their own role, so an admin cannot demote themselves
--     into a state where the console has no reachable owner;
--   * 'admin' can never be granted through the API - it is set by the project
--     owner in the SQL editor, which stops privilege escalation through the
--     moderation UI itself.
-- ============================================================================

create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.profiles
     where id = auth.uid()
       and role in ('moderator', 'admin')
  );
$$;

-- ----------------------------------------------------------------------------
-- Read-only console data
-- ----------------------------------------------------------------------------
create or replace function public.admin_overview()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_staff() then
    raise exception 'NOT_AUTHORISED' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'hunters',        (select count(*) from public.profiles),
    'new_last_7d',    (select count(*) from public.profiles where created_at > now() - interval '7 days'),
    'active_today',   (select count(distinct user_id) from public.study_sessions
                        where started_at >= date_trunc('day', now())),
    'sessions',       (select count(*) from public.study_sessions where status = 'completed'),
    'minutes',        (select coalesce(sum(credited_minutes), 0) from public.study_sessions
                        where status = 'completed'),
    'xp_awarded',     (select coalesce(sum(amount), 0) from public.xp_transactions),
    'guilds',         (select count(*) from public.guilds),
    'friendships',    (select count(*) from public.friendships where status = 'accepted'),
    'staff',          (select count(*) from public.profiles where role in ('moderator', 'admin'))
  );
end;
$$;

create or replace function public.admin_hunters(
  p_limit  integer default 25,
  p_search text default null
)
returns table (
  user_id          uuid,
  username         text,
  display_name     text,
  avatar_url       text,
  hunter_rank      text,
  level            integer,
  xp_total         bigint,
  sessions         integer,
  current_streak   integer,
  hunter_role      text,
  is_public        boolean,
  last_study_date  date,
  created_at       timestamptz
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_staff() then
    raise exception 'NOT_AUTHORISED' using errcode = '42501';
  end if;

  return query
    select p.id, p.username, p.display_name, p.avatar_url,
           p.rank::text, p.level, p.xp_total, p.sessions_completed,
           p.current_streak, p.role::text, p.is_public, p.last_study_date, p.created_at
      from public.profiles p
     where p_search is null
        or p.username ilike '%' || btrim(p_search) || '%'
     order by p.created_at desc
     limit greatest(1, least(coalesce(p_limit, 25), 100));
end;
$$;

-- ----------------------------------------------------------------------------
-- Role management
-- ----------------------------------------------------------------------------
create or replace function public.admin_set_role(p_user uuid, p_role public.hunter_role)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me   uuid := auth.uid();
  v_role public.hunter_role;
begin
  if v_me is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = '28000';
  end if;

  if not exists (
    select 1 from public.profiles where id = v_me and role = 'admin'
  ) then
    raise exception 'NOT_AUTHORISED' using errcode = '42501';
  end if;

  if p_user = v_me then
    raise exception 'CANNOT_CHANGE_OWN_ROLE' using errcode = '22023';
  end if;

  if p_role = 'admin' then
    raise exception 'ADMIN_GRANT_REQUIRES_OWNER' using errcode = '22023';
  end if;

  if not exists (select 1 from public.profiles where id = p_user) then
    raise exception 'HUNTER_NOT_FOUND' using errcode = 'P0002';
  end if;

  if not public.check_rate_limit('admin_set_role', 60, 3600) then
    raise exception 'RATE_LIMITED' using errcode = '54000';
  end if;

  update public.profiles
     set role = p_role,
         updated_at = now()
   where id = p_user
  returning role into v_role;

  insert into public.notifications (user_id, type, title, message)
  values (
    p_user,
    'system',
    'System role updated',
    'A System administrator set your role to ' || v_role::text || '.'
  );

  return jsonb_build_object('user_id', p_user, 'role', v_role);
end;
$$;

revoke all on function public.is_staff() from public;
revoke all on function public.admin_overview() from public;
revoke all on function public.admin_hunters(integer, text) from public;
revoke all on function public.admin_set_role(uuid, public.hunter_role) from public;

grant execute on function public.is_staff() to authenticated;
grant execute on function public.admin_overview() to authenticated;
grant execute on function public.admin_hunters(integer, text) to authenticated;
grant execute on function public.admin_set_role(uuid, public.hunter_role) to authenticated;
